(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-speculative-rollout-draft"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-1\">一 · 事故现场：一次 rollout 吞吐的塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-2\">二 · 它解决的推理问题：带宽受限下的串行 decode</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-3\">三 · 它不解决什么：边界清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-4\">四 · 适用边界的量化判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-5\">五 · 一个具体例子的代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-6\">六 · 一次接受率塌陷事故：投机采样在 RL rollout 里先解决什么、又栽在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-7\">七 · 当接受率跌破盈亏线：一次长 CoT rollout 的吞吐塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-8\">八 · 候选生成：draft 自回归与 γ 的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-9\">九 · 并行验证：一次目标前向吃掉 γ 个位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-10\">十 · 前缀接受与拒绝处重采样：分布无偏的那一刀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-11\">十一 · KV 增量写入与拒绝段丢弃：块表一致性是硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-12\">十二 · 循环终止与 logprob 记账：训练侧要的那份数据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-13\">十三 · 每步代价的合并视图与工程取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-14\">十四 · 接受率塌陷与负收益：投机采样在 RL rollout 中的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-15\">十五 · 接受概率公式的逐项拆解与无偏性推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-16\">十六 · 期望接受长度的闭式解与 γ 的边际收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-17\">十七 · 加速比公式与 c_draft/c_target 的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-18\">十八 · 可实现的伪代码：验证、接受、KV 增量写入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-19\">十九 · 拒绝率骤降时的公式反馈与 γ 自适应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-20\">二十 · 接受率塌陷与负加速：投机采样的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-21\">二十一 · 请求形态：长CoT才是配方的主菜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-22\">二十二 · 批大小与continuous batching的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-23\">二十三 · 并发结构与接受率的相互塑造</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-24\">二十四 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-25\">二十五 · 配方表：把判断落成可执行的分流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-26\">二十六 · 负载配方：什么样的请求才配得上投机采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-27\">二十七 · 硬件档位：按 draft 与 target 的显存比切三档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-28\">二十八 · 并行拓扑：验证前向的切分与 draft 的放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-29\">二十九 · 量化方案：draft 与 target 的精度不必一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-30\">三十 · KV 策略：只写接受段与块表一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-31\">三十一 · 调度参数：γ、批大小与同步节奏的联合整定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-32\">三十二 · 一个可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-33\">三十三 · 配方边界：接受率悬崖、显存水位与同步链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-34\">三十四 · 显存账：draft 模型不是免费的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-35\">三十五 · 带宽账：γ 个候选的并行验证读什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-36\">三十六 · 通信账：同步链路与拒绝候选的 KV 一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-37\">三十七 · 功耗与尾延迟：γ 放大的是方差不是均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-38\">三十八 · 规模上限：同步链路带宽与显存容量先约束谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-39\">三十九 · 吞吐归因：把加速比拆成可观测的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-40\">四十 · 规模上去以后，先崩的是同步链路而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-41\">四十一 · 接受率塌陷：从统计信号到根因定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-42\">四十二 · 精度问题：无偏性被破坏的三种路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-43\">四十三 · OOM 与 KV 碎片：被拒绝候选的账要算清</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-44\">四十四 · 批抖动与路由不均：continuous batching 下的接受率方差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-45\">四十五 · 尾延迟尖刺：长 CoT 样本的 p99 从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-46\">四十六 · 监控面板与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-47\">四十七 · 失效链与回滚判据：接受率塌陷、KV 碎片与批抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-48\">四十八 · 同族算法的分界线：改哪一段数据流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-49\">四十九 · 决策表：五个判据与三种结论</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-50\">五十 · γ与成本的联合选择：不是越大越好</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-51\">五十一 · 与近似加速的取舍：无偏是硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-52\">五十二 · 组合顺序与回退条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-rollout-draft-sec-53\">五十三 · 同族算法怎么选：投机采样的决策边界与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:540px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout引擎对每条采样请求先用draft模型自回归生成γ个候选tok…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标模型对这γ个候选做一次并行前向，得到每个位置的目标概率</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按min(1, p_target/p_draft)逐位置接受，遇到首个拒绝…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">接受的token连同重采样token追加到序列，KV只对接受段做增量写入，…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">重复上述循环直到EOS或max_len，rollout引擎记录每token…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-speculative-rollout-draft-sec-1\">一 · 事故现场：一次 rollout 吞吐的塌陷</h3>\n<p>某 RL 训练任务的 rollout 引擎在策略更新第 3 轮后出现吞吐塌陷：样本吞吐较基线下降，decode 时延上升，长 CoT 样本的生成时间占比进一步扩大。排查发现，引擎启用了投机采样，draft 模型仍是上一轮策略蒸馏出的权重，而目标模型已被本轮策略替换。策略分布漂移导致接受率骤降，γ 个候选token被逐位置拒绝，目标模型每轮只前进 1 个token，却额外承担了一次 draft 自回归与一次并行验证前向。此时加速比公式的分子塌到接近 1，分母却因 γ·c_draft/c_target 而膨胀，加速比低于 1，投机采样从加速器变成负收益。更隐蔽的是，被拒绝候选的 KV 若未及时回收，块表出现不一致，长 CoT 样本下 KV 池被无效块占用，进一步压缩了 continuous batching 的批容量。</p>\n<p>这个事故界定了本算法的问题域：它不解决 prefill 组织、不解决 KV 池化与分离，也不解决批调度本身；它只针对 decode 循环内逐 token 串行的带宽瓶颈，用 draft-verify 把串行步数压下来。事故的根因不在机制本身，而在适用边界被越过——策略分布漂移大时，draft 与目标模型不匹配，机制的前提失效。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-2\">二 · 它解决的推理问题：带宽受限下的串行 decode</h3>\n<p>RL rollout 的 decode 阶段是逐 token 串行：每生成一个 token，目标模型需完整读一遍权重与 KV cache，算力大量闲置，HBM 带宽成为瓶颈。长 CoT 样本动辄数千 token，生成时间占 rollout 总时长主导，直接拖慢 RL 训练的样本吞吐。投机采样的目标是把“每步 1 token”的串行结构改成“每步 γ+1 token 的并行验证”，让目标模型一次前向覆盖 γ 个候选位置，从而摊薄权重读取的带宽代价。</p>\n<p>机制按数据流顺序：rollout 引擎对每条采样请求先用 draft 模型自回归生成 γ 个候选 token 及其概率；目标模型对这 γ 个候选做一次并行前向，得到每个位置的目标概率；按逐位置接受概率</p>\n<div class=\"formula\">$$p_{\\text{accept}}=\\min\\left(1,\\frac{p_{\\text{target}}(x)}{p_{\\text{draft}}(x)}\\right)$$</div>\n<p>逐位置接受，遇到首个拒绝位置即停止，并从残差分布 $$\\left(p_{\\text{target}}-p_{\\text{draft}}\\right)^{+}$$ 重采样一个 token。接受的 token 连同重采样 token 追加到序列，KV 只对接受段做增量写入，被拒绝的候选 KV 丢弃；重复循环直到 EOS 或 max_len，引擎记录每 token 的 logprob 供训练侧重要性采样使用。期望每步 token 数为</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>其中 α 为逐位置接受率，c_draft/c_target 为 draft 与目标模型单次前向的相对代价。公式直接给出适用边界：α 高、γ 适中、c_draft 远小于 c_target 时收益成立；α 塌陷或 draft 代价上升时，分子趋近 1、分母大于 1，加速比低于 1。代价面同样明确：rollout 与训练的权重同步链路多一份模型，显存与同步开销增加；draft 需随策略更新频繁重训或蒸馏，同步滞后会进一步降低接受率。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-3\">三 · 它不解决什么：边界清单</h3>\n<p>本算法不改变 prefill/KV 组织。分块预填搭载解码、分离式预填解码 rollout 处理的是 prefill 与 decode 的资源错配，投机采样对此不置一词；它与 Rollout 前缀 KV 共享也无交集，后者复用前缀 KV 降低重复计算，而投机采样只在 decode 循环内做并行验证。分页 KV 批量 Rollout 管理的是块表与批内碎片，投机采样只要求被拒绝候选的 KV 回收与块表一致，不承担分页策略设计。</p>\n<p>它也不解决批不变采样与数值精度稳定化。输出分布无偏是它与近似加速方法的本质区别：接受-拒绝加残差重采样保证输出分布与目标模型严格一致，因此它不能与任何改变输出分布的近似手段混用而不加校正。它不解决在线剪枝、异构 Agent 协同、异步流水线调度——这些是样本级与系统级的吞吐手段，投机采样是 token 级的 decode 手段。规模上限受 draft 与目标模型同步链路带宽及显存容量约束：模型越大，多一份 draft 权重的显存代价与同步开销越重，γ 的并行验证也越受目标模型单次前向的显存带宽限制。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-4\">四 · 适用边界的量化判断</h3>\n<p>判断是否启用，先看接受率 α 的量级与稳定性。代码、格式化输出等结构化任务的 α 高，rollout decode 吞吐可提升 2–3 倍；开放式长 CoT 在策略早期漂移大时 α 低，加速比可能低于 1。工程上应把 α 作为运行时指标采集：按任务类型分桶统计接受长度分布，若某桶的期望每步 token 数长期接近 1，应关闭该桶的投机路径，回退到纯目标模型 decode，避免负收益。</p>\n<p>再看 γ 的选择。γ 增大提升期望 token 数，但目标模型单次前向的验证代价与 draft 自回归步数同步上升；γ 过大时，拒绝位置靠前导致大量候选 KV 被丢弃，长 CoT 样本下 KV 池容量被无效块占用。γ 应按 α 与 c_draft/c_target 联合调参，而非固定值。最后看同步链路：draft 重训/蒸馏的频率必须跟上策略更新节奏，同步滞后一轮就可能让 α 掉到阈值以下。显存预算需为 draft 权重与候选 KV 预留，否则 continuous batching 的批大小被迫压缩，吞吐收益被抵消。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>机制表现</th><th>系统代价</th></tr></thead><tbody><tr><td>α 高且稳定（代码、格式化）</td><td>期望每步 token 数显著大于 1</td><td>decode 吞吐提升 2–3 倍，显存多一份 draft</td></tr><tr><td>α 低（策略早期漂移）</td><td>首位置即拒绝，每轮仅前进 1 token</td><td>加速比低于 1，decode 时延上升</td></tr><tr><td>γ 过大</td><td>候选 KV 大量丢弃</td><td>KV 池碎片累积，批容量压缩</td></tr><tr><td>同步滞后</td><td>draft 与目标分布失配</td><td>接受率持续下降，同步开销上升</td></tr></tbody></table>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-5\">五 · 一个具体例子的代价核算</h3>\n<p>设某长 CoT 采样请求目标生成长度为数千 token，γ 取适中值，draft 单次前向代价远小于目标模型。若 α 高，每轮平均接受多个 token，目标模型前向次数按期望 token 数摊薄，decode 阶段的权重读取带宽被多次复用，rollout 样本吞吐上升；此时新增代价是 draft 权重的显存占用与每轮 draft 自回归的算力，但因 c_draft 远小于 c_target，分母增幅有限。若同一请求在策略更新后 α 塌陷，每轮只接受 1 个 token 加一次重采样，目标模型前向次数反而多于纯 decode，且每次前向还要多算 γ 个验证位置的 KV 写入与丢弃，decode 时延上升、吞吐下降。同一机制在两个 α 区间给出相反符号的收益，这就是适用边界必须前置判断的原因。</p>\n<p>工程判断落在三件事上：把 α 做成按任务桶的运行时指标并设回退阈值；把 γ 与 c_draft/c_target 联合调参而非固定；把 draft 权重同步纳入 rollout 与训练的同一权重链路，保证同步不滞后。被拒绝候选 KV 的回收必须与块表一致，否则长 CoT 样本下 KV 碎片会先于接受率成为瓶颈。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-6\">六 · 一次接受率塌陷事故：投机采样在 RL rollout 里先解决什么、又栽在哪</h3>\n<p>某条 RL 训练流水线在 SFT 冷启后进入在线阶段，rollout 引擎按常规配置挂了一个与初始策略同源的 draft 模型，γ 取 5，长 CoT 样本动辄数千 token。前几十个 step 一切正常，decode 吞吐明显高于纯目标模型串行解码；随后策略经若干次梯度更新开始偏离初始分布，draft 与当前策略的 KL 迅速拉大，接受率从高位塌到个位数。此时每轮验证 γ 个候选，往往在第一个位置就被拒绝，目标模型这一次并行前向只换来 1 个有效 token，却付出了 γ 个位置的验证算力与一次额外的 draft 自回归开销。按 <span class=\"formula\">$$\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</span> 估算，分子退化为接近 1，分母因 γ·c_draft 抬升而大于 1，加速比跌破 1——rollout 比不开投机还慢。更糟的是被拒绝候选的 KV 需要丢弃，块表若未与接受段严格对齐，长样本下无效块在 KV 池里累积，可用容量被蚕食，continuous batching 的批大小被迫下调，样本吞吐二次受损。这个事故界定了本方案要解决的具体问题：rollout 的 decode 阶段逐 token 串行，HBM 带宽受限而算力闲置，数千 token 的长 CoT 生成时间占据 rollout 总时长主导，直接压低 RL 训练的样本吞吐；它用 draft 自回归猜 γ 个候选、目标模型一次并行前向验证的方式，把串行链路上的带宽等待换成一次算力密集的批量校验。</p>\n<p>机制上它只动 decode 循环，不改 prefill 与 KV 组织，这一点必须说清楚以免与相邻方案混淆：它与 Rollout 前缀 KV 共享、分块预填搭载解码、分离式预填/解码 rollout 都不是同一层的东西，后三者调整的是 prefill 与 KV 的组织方式，而投机采样在既有的 decode 循环内做 draft-verify。逐位置接受概率为 <span class=\"formula\">$$p_{\\text{accept}}=\\min\\left(1,\\frac{p_{\\text{target}}(x)}{p_{\\text{draft}}(x)}\\right)$$</span>，遇首个拒绝即停止，并从残差分布 <span class=\"formula\">$$\\left(p_{\\text{target}}-p_{\\text{draft}}\\right)^{+}$$</span> 重采样一个 token；接受的 token 连同重采样 token 追加到序列，KV 只对接受段做增量写入，被拒候选的 KV 丢弃，循环至 EOS 或 max_len，同时 rollout 引擎逐 token 记录 logprob 供训练侧重要性采样。输出分布与目标模型严格一致，这是它与各类近似加速方法的本质分界——它买到的是无偏的吞吐，而不是用分布偏差换速度。期望每步 token 数为 <span class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$</span>，α 为逐位置接受率；α 高时该式随 γ 增长近线性，α 低时迅速饱和于 1 附近，这正是事故中 γ=5 却只落 1 个 token 的数学解释。</p>\n<p>由此划出适用边界。它擅长的是 draft 与目标策略高度同分布、输出结构可预测的负载：代码生成、格式化 JSON、模板化推理链，这类场景接受率高，rollout decode 吞吐可提升 2–3 倍，收益直接体现在长 CoT 样本的生成时延与 SLO 上的样本吞吐。它不解决 prefill 侧的长 prompt 开销，不解决 KV 容量不足，也不解决跨节点通信与批调度公平性；γ 的调大只放大高接受率下的收益，对低接受率区间反而放大验证浪费，因此 γ 必须按在线测得的 α 自适应，而不是固定常数。系统代价有三处硬约束：一是显存，rollout 与训练同步链路多一份 draft 模型，draft 与目标共享 tokenizer 与 KV 布局虽降低了引擎改动，但权重常驻仍占容量；二是同步带宽，draft 需随策略更新频繁重训或蒸馏，同步滞后会进一步压低 α，同步链路带宽与显存容量共同构成规模上限；三是块表一致性，被拒候选 KV 的丢弃必须与接受段严格对齐，否则长 CoT 下 KV 碎片累积。工程判断落在准入条件上：只有当在线监控的 α 稳定高于使 speedup>1 的阈值、且 draft 重训/蒸馏的同步周期短于策略漂移的时间尺度时，才应把投机采样挂进 rollout；否则应退回纯目标模型解码，把这份显存与同步带宽留给批大小与 KV 池。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-7\">七 · 当接受率跌破盈亏线：一次长 CoT rollout 的吞吐塌陷</h3>\n<p>某次 RL 训练进入第二轮策略更新后，rollout 侧的 decode 吞吐不升反降：长 CoT 样本（数千 token）的生成时间比首轮更长，样本吞吐被拖垮，训练侧等不到足够 batch。根因不是目标模型变慢，而是 draft 模型仍停留在上一轮策略的权重上——RL 早期策略分布漂移大，draft 与当前策略不匹配，逐位置接受概率 <span>p<sub>accept</sub>=min(1, p<sub>target</sub>(x)/p<sub>draft</sub>(x))</span> 大面积触底，首个拒绝位置频繁出现在候选串开头，γ 个候选里往往只接受一两个，验证前向的开销却照付。此时加速比近似为</p>\n<div class=\"formula\">$$\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}},\\quad \\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$</div>\n<p>其中 α 为平均接受率。α 一旦跌到使分子接近 1，而分母因 γ·c<sub>draft</sub>/c<sub>target</sub> 恒大于 1，加速比就落到 1 以下——这正是负收益区间。工程上必须把 α 当作在线监控指标：按模型版本、按请求类型（代码/格式化输出 vs 自由文本）分桶统计，跌破阈值即回退到纯目标模型 decode，而不是让整条 rollout 流水线陪着 draft 一起空转。</p>\n<p>这个算法解决的边界很窄也很明确：它只压缩 decode 循环内逐 token 串行的开销，不改变 prefill 与 KV 的组织方式，因此与 Rollout 前缀 KV 共享、分块预填搭载解码、分离式预填/解码 rollout 是正交手段而非替代品；它也不解决 HBM 带宽受限下算力闲置的结构性矛盾，只是把 γ 个候选塞进一次目标前向以提高算力利用率。它更不适用于策略分布剧烈漂移的早期训练、draft 与目标模型规模差距过大导致 c<sub>draft</sub> 不可忽略的场景，以及显存已被长 CoT 的 KV 池吃满、再塞一份 draft 权重就会触发换页的部署档位。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>系统表现</th><th>工程动作</th></tr></thead><tbody><tr><td>α 高（代码、格式化输出）</td><td>decode 吞吐提升 2–3 倍，输出分布无偏</td><td>保持 γ 较大，按 continuous batching 每轮并行验证</td></tr><tr><td>α 骤降（策略漂移、同步滞后）</td><td>加速比 &lt; 1，rollout 吞吐下降</td><td>熔断回退纯目标 decode，触发 draft 重训/蒸馏</td></tr><tr><td>块表不一致</td><td>被拒候选 KV 未回收，KV 碎片累积</td><td>拒绝段 KV 丢弃与块表回收做成同一事务</td></tr></tbody></table>\n<p>代价侧还有两条容易被低估的链路：draft 模型需随策略更新频繁重训或蒸馏，rollout 与训练之间多一份权重同步，同步带宽与显存容量共同构成规模上限；被拒绝候选的 KV 必须与块表回收严格一致，否则长 CoT 样本下无效块持续占用 KV 池，把本来用于提高 batch 的容量吃掉。判断是否启用，先看 α 的在线分布与 draft 权重的同步延迟，再看显存余量——三者任一不满足，投机采样在这条 rollout 上就是负资产。</p>\n<h3 id=\"alg-speculative-rollout-draft-sec-8\">八 · 候选生成：draft 自回归与 γ 的代价结构</h3>\n<p>一轮投机循环的起点在 rollout 引擎的 decode 循环内部：对每条处于解码态的采样请求，draft 模型（或挂在目标模型上的 Medusa/EAGLE 头）以自回归方式连续生成 γ 个候选 token，并同时输出这 γ 个位置的 draft 概率 <em>p</em><sub>draft</sub>(x)。输入是当前已接受前缀的 KV 与最后一个 token；输出是长度 γ 的候选序列加上逐位置概率向量。这一步的代价是 γ 次串行前向，但因为 draft 模型参数量远小于目标模型，单步延迟被压到目标模型单步的若干分之一，记为 c<sub>draft</sub>。真正决定这一步经济性的是 γ 的取值：γ 太小，验证阶段的并行收益摊不开固定开销；γ 太大，draft 自回归的串行段变长，且被拒绝的候选比例上升，白算的 KV 写入增多。</p>\n<p>从带宽角度看，draft 自回归仍是逐 token 的 HBM 读权重过程，只是权重体量小，单位 token 的字节读取量低，因此它把原本闲置的算力占用一部分、把带宽压力从目标模型转移出来。工程上这一步的显存代价还包括 draft 权重常驻：它与目标模型共享 tokenizer 与 KV 布局，但权重是独立的一份，在 NVL72 这类多卡部署中，draft 往往与目标模型同卡放置以避免额外一跳通信，代价是每卡可用 KV 池容量被压缩。以长 CoT 样本（数千 token）为例，若 γ 取 4–8，draft 段在整轮循环中的时间占比随 c<sub>draft</sub>/c<sub>target</sub> 线性上升，这个比值就是公式中惩罚项的分母来源。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-9\">九 · 并行验证：一次目标前向吃掉 γ 个位置</h3>\n<p>候选生成完成后，目标模型对这 γ 个候选做一次并行前向。输入是前缀 KV 拼接上 γ 个候选 token 的嵌入，输出是每个候选位置上的目标分布 <em>p</em><sub>target</sub>(x)。关键机制在于这次前向把 γ 个位置的验证合并为一个 batch 维度的矩阵乘，原本需要 γ 次串行目标前向的工作被压成一次，算力利用率从逐 token 解码时的低位抬升到接近预填阶段的水平，而 HBM 侧只需读一遍目标权重。这就是投机采样在 decode 阶段把带宽受限转为算力受限的核心动作。</p>\n<p>代价体现在 KV 的临时占用上：验证前向需要为 γ 个候选位置写入临时 KV，这些位置在验证结果出来前都占着块表条目。若 γ 偏大且接受率偏低，临时 KV 的写入与随后的丢弃构成纯浪费，在长 CoT 样本下会显著抬高 KV 池的瞬时水位。另一个代价是验证前向的延迟不再是单 token 延迟，而是接近一次小批量前向的延迟，对 SLO 中 decode 时延的尾部有直接影响；连续批处理下，多请求的验证前向可以拼批，把固定开销摊薄，但拼批会拉长单请求的验证等待。</p>\n<div class=\"formula\">$$p_{\\text{accept}}=\\min\\left(1,\\frac{p_{\\text{target}}(x)}{p_{\\text{draft}}(x)}\\right)$$</div>\n<p>逐位置接受概率由上式给出，验证阶段输出的就是这 γ 个位置的 p<sub>target</sub> 与 p<sub>draft</sub> 之比，供下一步裁决使用。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-10\">十 · 前缀接受与拒绝处重采样：分布无偏的那一刀</h3>\n<p>裁决按位置从左到右进行：对第 i 个候选，以 p<sub>accept</sub> 的概率接受，一旦某位置被拒绝即刻停止，后续候选全部作废。被拒绝的位置不再沿用 draft 的采样结果，而是从残差分布 (p<sub>target</sub> − p<sub>draft</sub>)<sup>+</sup> 重新采样一个 token 补上。输入是验证阶段得到的逐位置双概率；输出是“接受段 + 一个重采样 token”的追加序列。这一步的计算量极小，但它是整个机制保证输出分布与目标模型严格一致的关键：接受段的每个 token 都满足重要性修正，拒绝处的重采样恰好补回被 draft 高估的那部分概率质量，两者相加逐位置还原目标分布。</p>\n<p>系统代价在于裁决的串行性：接受判定必须按位置顺序做，因为首个拒绝位置决定了后续全部作废，这个串行段无法与验证前向重叠，构成了每轮循环的固定尾延迟。工程实现上通常把 γ 个位置的均匀随机数与概率比一次性算好，再用前缀扫描（prefix scan）找首个拒绝位置，把串行裁决压成一次轻量 kernel，避免逐位置 launch 的开销。对长 CoT 样本，这个尾延迟在每轮循环中重复数千除以平均接受长度次，累计影响不可忽略，因此 γ 的选择要与裁决 kernel 的固定开销匹配。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-11\">十一 · KV 增量写入与拒绝段丢弃：块表一致性是硬约束</h3>\n<p>裁决完成后进入 KV 落账：只对接受段（含重采样 token）做增量写入，把验证阶段写入的临时 KV 中属于接受前缀的部分转正，被拒绝的候选 KV 直接丢弃。输入是接受长度与临时块表映射；输出是更新后的序列 KV 与块表。这一步的代价是块表操作的原子性要求——被丢弃的候选块必须从块表中摘除并归还池，否则在长 CoT 样本的数千轮循环里，无效块会持续累积，KV 池容量被无效块占用，最终触发抢占或换出，把投机带来的吞吐收益吃掉。</p>\n<p>另一个代价是写入粒度：接受段长度每轮不同（从 1 到 γ+1 不等），KV 写入呈现变长突发，分页式 KV 管理下每轮要做一次块分配与映射更新，分配器的锁竞争在多请求并发时成为热点。工程判断是让 draft 与目标模型共享同一套 KV 布局与块表语义，使临时 KV 与正式 KV 落在同一地址空间，接受段的转正退化为块表条目的状态翻转而非数据搬迁，从而把这一步的带宽代价降到接近零；这也是“rollout 引擎改动局限于 decode 循环”这一说法的物理基础。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-12\">十二 · 循环终止与 logprob 记账：训练侧要的那份数据</h3>\n<p>一轮循环结束后，rollout 引擎检查是否遇到 EOS 或达到 max_len，未终止则回到候选生成步骤，用更新后的前缀 KV 继续下一轮。输入是追加后的序列与 KV；输出是下一轮的 draft 起点。每轮平均产出 token 数由公式给出：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>其中 α 为逐位置接受率。这个式子把每轮的有效产出与 draft 开销的比值钉死：α 高时分子接近 γ+1，加速比随 γ 上升；α 低时分子趋近 1，分母却因 γ·c<sub>draft</sub> 变大，加速比跌破 1，rollout 吞吐反而下降——这正是 RL 训练早期策略分布漂移时接受率骤降的负收益来源。与此同时，引擎必须记录每个被接受 token 的 logprob（来自验证阶段的目标分布，而非 draft 分布），供训练侧重要性采样使用；记账的代价是每 token 一份标量写回，在数千 token 的长 CoT 样本上构成可观的 host 侧写带宽，通常以异步方式批量回传，避免阻塞 decode 循环。</p>\n<p>循环终止时的收尾代价还包括：最后一轮可能只接受部分候选，剩余临时 KV 需统一清理；若请求在 max_len 处截断，未完成的候选段同样要走丢弃路径。把这几条路径的块表状态收敛到同一不变量，是 rollout 引擎在 decode 循环内做最小改动时必须验证的工程点。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-13\">十三 · 每步代价的合并视图与工程取舍</h3>\n<p>把五步的代价按数据流合并：候选生成付出 γ·c<sub>draft</sub> 的串行延迟与一份 draft 权重显存；并行验证付出一次小批量前向延迟与 γ 个位置的临时 KV；裁决付出一次前缀扫描的尾延迟；KV 落账付出块表原子操作与变长分配的锁竞争；记账付出每 token 标量写回。整轮循环的墙钟时间近似为 γ·c<sub>draft</sub> + c<sub>verify</sub> + c<sub>commit</sub> + c<sub>book</sub>，而有效产出是 E[tokens/step]，两者之比就是单请求的 decode 吞吐。批调度层面，连续批处理把多请求的验证前向拼批以摊薄 c<sub>verify</sub>，但拼批会拉长单请求的验证等待，SLO 上表现为 decode 时延尾部变厚，容量规划需按接受率分布而非均值来定批大小。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>候选生成</td><td>前缀 KV、末 token</td><td>γ 候选 + p<sub>draft</sub></td><td>γ·c<sub>draft</sub> 串行延迟、draft 权重显存</td></tr><tr><td>并行验证</td><td>前缀 KV + γ 候选</td><td>逐位置 p<sub>target</sub></td><td>一次小批量前向延迟、γ 位置临时 KV</td></tr><tr><td>前缀接受/重采样</td><td>双概率向量</td><td>接受段 + 1 token</td><td>前缀扫描尾延迟</td></tr><tr><td>KV 落账</td><td>接受长度、块表</td><td>转正 KV、归还块</td><td>块表原子操作、变长分配锁竞争</td></tr><tr><td>记账/循环</td><td>接受 token 的目标 logprob</td><td>训练侧重要性采样数据</td><td>每 token 标量写回带宽</td></tr></tbody></table>\n<p>工程取舍落在 γ 与批大小的联合选择上：γ 增大抬高 E[tokens/step] 但同步抬高 c<sub>draft</sub> 与临时 KV 水位，批大小增大摊薄 c<sub>verify</sub> 但拉长单请求尾延迟。在代码、格式化输出这类接受率高的形态下，γ 取较大值、批按 continuous batching 组织即可吃到 2–3 倍 decode 吞吐；而在策略分布漂移大的早期训练，正确动作是把 γ 压到 1–2 并缩短 draft 重训/蒸馏的同步周期，用同步链路的带宽换接受率，而不是硬撑大 γ 让加速比跌破 1。被拒绝候选 KV 的丢弃路径必须与块表状态机共用同一不变量，否则长 CoT 样本下 KV 碎片累积会先于接受率成为吞吐瓶颈。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-14\">十四 · 接受率塌陷与负收益：投机采样在 RL rollout 中的失效边界</h3>\n<p>投机采样在 decode 循环里的收益完全由一个比值决定：目标模型与 draft 模型分布的接近程度。RL 训练早期，策略分布相对参考模型漂移剧烈，draft 模型（或 EAGLE/Medusa 头）若仍停留在上一轮策略上，逐位置接受概率 $p_{\\text{accept}}=\\min\\left(1,\\frac{p_{\\text{target}}(x)}{p_{\\text{draft}}(x)}\\right)$ 会系统性偏低，首个拒绝位置前移，每轮实际产出 token 数迅速向 1 收敛。此时验证前向的代价已经付出，却只换来一个 token，加速比公式 $\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$ 的分子趋近 1、分母大于 1，结果小于 1——rollout 吞吐不升反降，长 CoT 样本的数千 token 生成被拖得更长。</p>\n<p>失效条件可以按数据流定位到三个环节。其一，draft 自回归生成 γ 个候选这一步，若 draft 与当前策略的 KL 距离超过阈值，候选前缀在第一个位置就被拒，γ 的并行验证预算全部浪费；其二，目标模型并行前向验证 γ 个位置，算力开销与 γ 成正比而与接受长度无关，拒绝越早，单位有效 token 的算力成本越高；其三，KV 增量写入只覆盖接受段，被拒候选的 KV 必须丢弃，若块表未同步回收，长 CoT 场景下 KV 池会被无效块持续占用，显存压力在样本长度增长时放大。三者叠加，构成“接受率低→验证浪费→KV 碎片→批容量下降”的正反馈。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>draft 自回归</td><td>已接受前缀</td><td>γ 个候选及概率</td><td>γ 次串行前向，draft 权重常驻显存</td></tr><tr><td>目标并行验证</td><td>γ 个候选</td><td>逐位置目标概率</td><td>一次前向算力，与 γ 成正比</td></tr><tr><td>前缀接受与重采样</td><td>两套概率</td><td>接受段 + 1 个残差 token</td><td>首个拒绝即停，后续候选作废</td></tr><tr><td>KV 增量写入</td><td>接受段</td><td>块表更新</td><td>被拒 KV 丢弃，需块表一致</td></tr></tbody></table>\n<p>工程判断落在同步链路而非算法本身：draft 模型必须随策略更新重训或蒸馏，rollout 与训练之间多一份权重同步，同步滞后直接转化为接受率下降，同步带宽与显存容量共同构成规模上限。可行的边界做法是把 γ 与接受率阈值绑定——当滑动窗口接受率低于使分母等于分子的临界点，即 $\\mathbb{E}[\\text{tokens/step}] \\le 1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}$ 时，rollout 引擎应退回纯目标模型逐 token 解码，避免负收益；同时把 draft 重训节奏对齐策略版本号，而非固定步数，让接受率在策略漂移期可控。</p>\n<h3 id=\"alg-speculative-rollout-draft-sec-15\">十五 · 接受概率公式的逐项拆解与无偏性推导</h3>\n<p>投机采样的正确性不依赖任何近似，它由逐位置接受概率这一项撑起来。把目标模型分布记作 <span class=\"inline-math\">p_t(x)</span>，draft 分布记作 <span class=\"inline-math\">p_d(x)</span>，候选 token 为 <span class=\"inline-math\">x</span>，则接受概率写成</p>\n<div class=\"formula\">$$p_{\\text{accept}}=\\min\\left(1,\\frac{p_{\\text{target}}(x)}{p_{\\text{draft}}(x)}\\right)$$</div>\n<p>逐项看：分子是目标模型在该位置的归一化概率，分母是 draft 模型给出的同一位置概率，比值刻画“draft 相对目标高估了这个 token 多少”。取 min 与 1 的作用是把比值截断在上界 1，使接受概率天然落在 [0,1]，不需要额外归一化；这也意味着当 <span class=\"inline-math\">\\(p_t(x) \\ge p_d(x)\\)</span> 时该 token 必被接受，只有 draft 高估的 token 才承担被拒风险。分母 <span class=\"inline-math\">p_d(x)</span> 必须严格大于零，工程上要在 draft 侧对概率做下限截断（例如加一个极小 epsilon 后再归一化），否则比值发散。</p>\n<p>推导的关键一步在拒绝分支。设某位置被拒，我们需要证明从残差分布重采样后，该位置最终输出 token 的边缘分布恰好等于 <span class=\"inline-math\">p_t</span>。对任意 token <span class=\"inline-math\">x</span>，其被输出的总概率为“被接受”与“被拒后重采样命中”两部分之和：</p>\n<div class=\"formula\">$$p_{\\text{out}}(x)=\\min\\left(1,\\frac{p_t(x)}{p_d(x)}\\right)p_d(x)+\\left(1-\\sum_{x'}\\min\\left(1,\\frac{p_t(x')}{p_d(x')}\\right)p_d(x')\\right)\\cdot\\frac{\\left(p_t(x)-p_d(x)\\right)^{+}}{Z}$$</div>\n<p>关键一步是把第一项化简：当 <span class=\"inline-math\">\\(p_t \\ge p_d\\)</span> 时它等于 <span class=\"inline-math\">p_d(x)</span>，当 <span class=\"inline-math\">p_t < p_d</span> 时它等于 <span class=\"inline-math\">p_t(x)</span>，统一写作 <span class=\"inline-math\">min(p_t(x), p_d(x))</span>。于是第一项就是两个分布的逐点下确界。而拒绝概率 <span class=\"inline-math\">\\(1-\\sum_{x'}\\min(p_t,p_d)\\)</span> 恰好等于残差分布 <span class=\"inline-math\">(p_t-p_d)^{+}</span> 的总质量 <span class=\"inline-math\">Z</span>，因为 <span class=\"inline-math\">\\(\\sum_x (p_t-p_d)^{+} = 1-\\sum_x \\min(p_t,p_d)\\)</span>。两者相消，第二项化为 <span class=\"inline-math\">(p_t(x)-p_d(x))^{+}</span>。相加得 <span class=\"inline-math\">min(p_t,p_d)+(p_t-p_d)^{+}=p_t(x)</span>，逐点成立，无偏性得证。这个推导同时说明：残差分布必须用 <span class=\"inline-math\">(p_t-p_d)^{+}</span> 而不是 <span class=\"inline-math\">|p_t-p_d|</span>，否则总质量对不上，输出分布会被系统性拉偏。</p>\n<p>工程代价落在数值精度上。目标概率与 draft 概率都要在验证前向里取出并做逐位置比较，若目标模型跑 FP8 或 NVFP4，概率向量的量化误差会直接进入比值；在 <span class=\"inline-math\">p_d</span> 很小的尾部 token 上，比值对量化噪声极其敏感，容易出现“本该接受却被拒”的抖动。稳妥做法是让 logits 到概率的 softmax 与接受判定在 FP32 累加域完成，只让矩阵乘走低精度。另一项代价是残差重采样需要一次额外的采样算子调用与一次概率张量物化，在批内每条请求上都要做，属于纯带宽开销。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-16\">十六 · 期望接受长度的闭式解与 γ 的边际收益</h3>\n<p>每轮验证能推进多少 token，决定了加速比的上界。设单 token 接受率为 <span class=\"inline-math\">\\(\\alpha\\)</span>（即 <span class=\"inline-math\">E[min(1,p_t/p_d)]</span> 在典型位置上的均值），并近似认为各位置独立同分布，则一轮内接受长度 <span class=\"inline-math\">L</span> 服从截断几何分布：接受 <span class=\"inline-math\">k</span> 个后在第 <span class=\"inline-math\">k+1</span> 个被拒，或全部 <span class=\"inline-math\">\\(\\gamma\\)</span> 个都被接受。其期望为</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$</div>\n<p>逐项解释：分子 <span class=\"inline-math\">\\(1-\\alpha^{\\gamma+1}\\)</span> 是“至少有一个位置被拒或走满 γ”的概率质量归一化项；分母 <span class=\"inline-math\">\\(1-\\alpha\\)</span> 是几何分布的标准化因子。当 <span class=\"inline-math\">\\(\\gamma \\to \\infty\\)</span> 时该式趋于 <span class=\"inline-math\">\\(1/(1-\\alpha)\\)</span>，这就是理论上限——接受率 0.8 时上限是每步 5 个 token，接受率 0.5 时上限只有 2 个。注意这个期望里已经包含了“拒绝处额外重采样 1 个 token”的贡献，所以 <span class=\"inline-math\">\\(\\gamma=0\\)</span> 时公式退化为 1，与逐 token 解码一致，可作为实现时的自检点。</p>\n<p>对 <span class=\"inline-math\">\\(\\gamma\\)</span> 求差分可以看出边际收益递减：每多猜一个候选，期望增量是 <span class=\"inline-math\">\\(\\alpha^{\\gamma}(1-\\alpha)/(1-\\alpha)=\\alpha^{\\gamma}\\)</span>，随 <span class=\"inline-math\">\\(\\gamma\\)</span> 指数衰减。这意味着把 <span class=\"inline-math\">\\(\\gamma\\)</span> 从 4 拉到 8，在 <span class=\"inline-math\">\\(\\alpha=0.7\\)</span> 时只多带来约 <span class=\"inline-math\">\\(0.7^4\\approx0.24\\)</span> 个 token/步的期望收益，而验证前向的计算量与 KV 写入量却线性增长。γ 的选取因此不是越大越好，而是要让“每步多验证一个候选的边际 token 收益”与“该候选带来的额外验证算力、KV 带宽”打平。</p>\n<p>这里有一个必须点明的近似：独立性假设在长 CoT 样本上并不严格成立。代码、结构化输出里相邻 token 高度相关，一旦某位置被拒，后续位置的 draft 质量往往同步变差，实际接受长度会短于闭式解预测。因此 <span class=\"inline-math\">\\(\\alpha\\)</span> 应当按位置分桶统计（例如按 token 类型或按序列位置区间），用分桶均值代入公式做容量规划，而不是全局一个标量。工程上这对应 rollout 引擎里一张按请求类型维护的接受率滑动表，用于动态调 <span class=\"inline-math\">\\(\\gamma\\)</span>。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-17\">十七 · 加速比公式与 c_draft/c_target 的代价结构</h3>\n<p>期望 token 数只是分子，真实加速比还要除以每步的相对成本：</p>\n<div class=\"formula\">$$\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>分母里 1 代表目标模型一次并行验证前向的成本（归一化为单位 1），<span class=\"inline-math\">\\(\\gamma\\cdot c_{\\text{draft}}\\)</span> 是 draft 模型自回归生成 γ 个候选的总成本，<span class=\"inline-math\">\\(c_{\\text{draft}}/c_{\\text{target}}\\)</span> 是单 token draft 前向相对单 token 目标前向的成本比。这个比值是整套方案的经济学核心：draft 模型越小，比值越低，但接受率 <span class=\"inline-math\">\\(\\alpha\\)</span> 也越低，两个方向互相拉扯。把 <span class=\"inline-math\">\\(\\alpha\\)</span> 写成 <span class=\"inline-math\">\\(c_{\\text{draft}}/c_{\\text{target}}\\)</span> 的隐函数后可以发现，存在一个最优的 draft 规模区间，超出后加速比反而下降。</p>\n<p>关键推导一步是把分母拆成“验证成本”与“draft 成本”两部分看渐近行为。当 <span class=\"inline-math\">\\(\\alpha\\)</span> 很高、<span class=\"inline-math\">\\(\\gamma\\)</span> 适中时，<span class=\"inline-math\">E[tokens/step]</span> 接近 <span class=\"inline-math\">\\(\\gamma+1\\)</span>，分母约等于 <span class=\"inline-math\">\\(1+\\gamma r\\)</span>（记 <span class=\"inline-math\">\\(r=c_{\\text{draft}}/c_{\\text{target}}\\)</span>），加速比趋于 <span class=\"inline-math\">\\((\\gamma+1)/(1+\\gamma r)\\)</span>。若 <span class=\"inline-math\">r</span> 远小于 1（draft 是目标模型的几十分之一），该式趋近 <span class=\"inline-math\">\\(\\gamma+1\\)</span>，即加速比上限就是每轮验证的候选数加一；若 <span class=\"inline-math\">r</span> 接近 1（draft 与目标同量级），加速比趋近 1，投机完全失效。这解释了为什么 Medusa/EAGLE 头这类“轻量附加结构”在成本比上占优：它们不引入独立的小模型前向，而是复用目标模型的隐藏状态，<span class=\"inline-math\">r</span> 被压到很低。</p>\n<p>代价的另一个来源是 KV。验证前向要对 γ 个候选一次性算出目标概率，这要求把候选 token 的 KV 也喂进注意力，于是每步的 KV 读带宽是逐 token 解码的 γ 倍量级；被拒候选的 KV 随后丢弃，等于白读了这段带宽。在 HBM 带宽受限的 decode 阶段，这部分浪费直接体现为有效带宽利用率下降。长 CoT 样本（数千 token）下，KV 池的读写压力本就接近饱和，γ 增大带来的带宽放大必须计入容量规划。功耗侧同理：验证前向把算力从闲置拉满，单步功耗尖峰高于逐 token 解码，连续批处理下多请求的验证前向叠在一起会推高整卡功耗包络。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-18\">十八 · 可实现的伪代码：验证、接受、KV 增量写入</h3>\n<p>把公式落到 decode 循环，核心是一个“draft 展开—并行验证—前缀接受—残差重采样—KV 提交”的状态机。下面给出与硬件无关的伪代码思路，重点在块表一致性与概率张量的生命周期。</p>\n<ul>\n<li>输入：当前序列 <span class=\"inline-math\">s</span>、已提交 KV 块表 <span class=\"inline-math\">B</span>、候选宽度 <span class=\"inline-math\">\\(\\gamma\\)</span>、目标模型 <span class=\"inline-math\">T</span>、draft 模型 <span class=\"inline-math\">D</span>。</li>\n<li>第一步：<span class=\"inline-math\">D</span> 以 <span class=\"inline-math\">s</span> 为前缀自回归跑 <span class=\"inline-math\">\\(\\gamma\\)</span> 步，产出候选 token 数组 <span class=\"inline-math\">\\(x[0..\\gamma-1]\\)</span> 与对应 <span class=\"inline-math\">p_d[i]</span>（全词表概率或至少 top-k 稀疏表示）。</li>\n<li>第二步：把 <span class=\"inline-math\">x</span> 拼到 <span class=\"inline-math\">s</span> 后，<span class=\"inline-math\">T</span> 做一次并行前向，得到每个位置的 <span class=\"inline-math\">p_t[i]</span>；此处的 KV 写入指向临时块表 <span class=\"inline-math\">B'</span>，与已提交的 <span class=\"inline-math\">B</span> 分离。</li>\n<li>第三步：从 <span class=\"inline-math\">i=0</span> 起逐位置抽 <span class=\"inline-math\">\\(u\\sim U(0,1)\\)</span>，若 <span class=\"inline-math\">\\(u &lt; \\min(1,p_t[i](x_i)/p_d[i](x_i))\\)</span> 则接受并继续，否则在位置 <span class=\"inline-math\">i</span> 停下，记 <span class=\"inline-math\">k=i</span> 为接受长度。</li>\n<li>第四步：若 <span class=\"inline-math\">\\(k &lt; \\gamma\\)</span>，用 <span class=\"inline-math\">(p_t[k]-p_d[k])^{+}</span> 归一化后重采样一个 token <span class=\"inline-math\">y</span>，把 <span class=\"inline-math\">x[0..k-1]</span> 与 <span class=\"inline-math\">y</span> 追加到 <span class=\"inline-math\">s</span>；若 <span class=\"inline-math\">\\(k=\\gamma\\)</span>，全部接受，无重采样。</li>\n<li>第五步：把 <span class=\"inline-math\">B'</span> 中对应前 <span class=\"inline-math\">k</span> 个候选的块提交进 <span class=\"inline-math\">B</span>，位置 <span class=\"inline-math\">k</span> 的重采样 token 需要一次单 token 前向来补它的 KV；位置 <span class=\"inline-math\">\\(k+1..\\gamma-1\\)</span> 的临时块整块释放回池。</li>\n<li>第六步：记录本步每个输出 token 的 <span class=\"inline-math\">\\(\\log p_t\\)</span> 供训练侧重要性采样，更新接受率滑动统计，按策略调整下一轮的 <span class=\"inline-math\">\\(\\gamma\\)</span>。</li>\n</ul>\n<p>伪代码里最容易出错的是第五步的块表提交顺序。临时块表 <span class=\"inline-math\">B'</span> 与已提交 <span class=\"inline-math\">B</span> 必须是两套独立的块 ID 空间，提交时按前缀做原子替换，否则一旦中途异常退出，<span class=\"inline-math\">B</span> 里会残留半提交的候选块，长 CoT 样本反复迭代后表现为 KV 碎片累积、池容量被无效块占用。另一个实现细节是重采样 token 的 KV 补齐：它不在验证前向的 γ 个位置里，必须单独跑一次前向，这次前向的延迟直接加在每步的关键路径上，是投机解码相对逐 token 解码多出来的固定开销之一。工程上可以把这次补齐与下一轮的 draft 生成重叠，用异步流水掩盖。</p>\n<p>数值层面，接受判定必须在 FP32 域比较，而 <span class=\"inline-math\">p_d</span> 的稀疏表示（top-k）会引入截断误差：被截断的尾部 token 概率被置零，导致 <span class=\"inline-math\">p_d(x)=0</span> 时比值无定义。实现上要么对 <span class=\"inline-math\">p_d</span> 做全词表物化（带宽代价），要么在截断处把该 token 的接受概率直接置 1 并跳过比值计算——后者在数学上等价于把 draft 分布视为“对尾部无意见”，但会轻微改变残差分布的质量分配，需要在训练侧 logprob 记录时保持一致口径。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-19\">十九 · 拒绝率骤降时的公式反馈与 γ 自适应</h3>\n<p>RL 训练早期策略分布漂移大，draft 与当前策略不匹配，<span class=\"inline-math\">\\(\\alpha\\)</span> 会从代码类任务的高位快速跌落。把 <span class=\"inline-math\">\\(\\alpha\\)</span> 代回加速比公式可以看到负收益的临界点：令 speedup=1，解出 <span class=\"inline-math\">\\(E[tokens/step]=1+\\gamma r\\)</span>。当 <span class=\"inline-math\">r</span> 固定时，这个等式给出一个临界接受率 <span class=\"inline-math\">\\(\\alpha^{*}\\)</span>，低于它投机就是净亏——每步验证的 γ 倍 KV 带宽和 draft 前向成本都付了，却只推进了不到一个 token 的等效工作量。工程判断因此不是“开不开投机”，而是“按请求类型和训练阶段动态开关”。</p>\n<p>具体机制是把 <span class=\"inline-math\">\\(\\gamma\\)</span> 做成接受率的函数：维护每条请求（或每个请求类型桶）的近期接受率 <span class=\"inline-math\">\\(\\hat\\alpha\\)</span>，按 <span class=\"inline-math\">\\(\\gamma = \\arg\\max_{\\gamma} \\frac{1-\\hat\\alpha^{\\gamma+1}}{(1-\\hat\\alpha)(1+\\gamma r)}\\)</span> 取整后裁剪到 [1, γ_max]。这个 argmax 没有闭式解，但可以离线打表：给定 <span class=\"inline-math\">r</span> 与 <span class=\"inline-math\">\\(\\hat\\alpha\\)</span> 的网格，预先算出最优 γ，运行时只做查表与插值，代价可忽略。当 <span class=\"inline-math\">\\(\\hat\\alpha\\)</span> 跌破临界值时把 γ 置 0，即退回逐 token 解码，避免负收益。</p>\n<p>代价在于反馈环路的滞后。接受率统计是滑动的，策略更新后 draft 权重同步本身也有延迟，两者叠加会让 γ 在策略切换后的若干步内仍停留在旧值，这段时间的 rollout 吞吐被浪费。缓解手段是把 draft 重训/蒸馏的节奏与 γ 自适应解耦：γ 自适应是秒级、按批内统计即时调整；draft 权重同步是分钟级、按策略版本触发。同步滞后期间用保守 γ（例如上限砍半）运行，把负收益窗口压到最小。显存侧则要预留 draft 模型的常驻权重与它自己的 KV 布局，这部分开销在长 CoT 大 batch 下与目标模型 KV 池争抢同一块 HBM，容量规划时必须把两份 KV 一起算。</p>\n<p>最后落到一个可操作的工程判断：把接受率当作一等指标暴露给调度器，让连续批处理在组批时优先把高接受率的请求（代码、格式化输出）与低接受率的请求（开放式推理）分开成批，各自用不同的 γ。这样公式里的 <span class=\"inline-math\">\\(\\alpha\\)</span> 在批内是同质的，闭式解才有意义；混批会让批内接受率方差变大，γ 只能取保守值，整体加速比被拉低。这个分桶逻辑不改 prefill/KV 组织，只动 decode 循环里的候选宽度与组批策略，与分页 KV、分离式预填等机制正交。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-20\">二十 · 接受率塌陷与负加速：投机采样的边界条件</h3>\n<p>把加速比公式拆开看，分子是每轮期望产出 token 数，分母是目标模型一次验证前向加 γ 次 draft 前向的相对代价。真正决定收益符号的是 α 与 c_draft/c_target 的比值：当 α 从 0.8 掉到 0.3、γ 取 5 时，分子从约 3.7 掉到约 1.8，而分母里 γ·c_draft/c_target 这一项不随 α 变化，于是加速比迅速逼近甚至跌破 1。RL rollout 的失效点恰在这里——训练早期策略分布漂移剧烈，draft 模型（或 EAGLE 头）还停留在上一版策略上，p_draft 与 p_target 的逐位置比值大面积落到 min(1, ·) 的下界之外，接受段长度退化为个位数甚至 0。此时每轮只吐 1 个重采样 token，却额外付出 γ 次 draft 前向的带宽与算力，rollout decode 吞吐反而低于纯目标模型串行解码。</p>\n<div class=\"formula\">$$\\text{speedup}&lt;1 \\iff \\mathbb{E}[\\text{tokens/step}] &lt; 1+\\gamma\\cdot\\frac{c_{\\text{draft}}}{c_{\\text{target}}}$$</div>\n<p>工程上要把这个不等式当作在线判据而非事后统计：rollout 引擎应按请求或按 batch 维度滑动统计实际接受段长度，一旦低于阈值就临时把 γ 降到 1 或直接旁路 draft 路径。这比离线评估更可靠，因为同一批采样请求内部，代码与格式化输出段的 α 高、自由推理段与长 CoT 中间步骤的 α 低，混合负载下全局平均会掩盖局部塌陷。γ 的选取也不是越大越好：γ 增大提升分子上限，但分母线性增长，且长 CoT 场景下被拒绝候选的 KV 丢弃量随 γ 上升，块表回滚与碎片整理的开销同步放大。</p>\n<p>第二类代价来自权重同步链路。draft 模型必须随策略更新重训或蒸馏，rollout 侧因此多驻留一份模型权重，显存占用与目标模型同量级时直接压缩 KV 池可用容量——长 CoT 样本数千 token、批大小按 continuous batching 组织，KV 池本已紧张，多一份 draft 权重意味着并发请求数下降，吞吐收益被并发损失抵消。同步滞后还会自我强化：draft 越旧，α 越低，越需要频繁重训，形成正反馈。第三类是 KV 一致性风险，被拒绝候选的 KV 必须按块表精确回滚，若增量写入与丢弃不在同一事务边界内完成，长 CoT 样本下无效块会持续占用 KV 池，表现为可用块缓慢泄漏而非立即报错。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>策略漂移致 α 骤降</td><td>接受段长度滑动均值走低</td><td>加速比 &lt; 1，decode 吞吐倒退</td><td>降 γ 或旁路 draft</td></tr><tr><td>draft 同步滞后</td><td>重训间隔内 α 单调下滑</td><td>多一份权重显存、同步带宽占用</td><td>缩短蒸馏周期、异步同步</td></tr><tr><td>KV 回滚不一致</td><td>KV 池可用块缓慢下降</td><td>长 CoT 并发容量被无效块挤占</td><td>块表事务化回滚</td></tr></tbody></table>\n<p>因此该方案的适用边界应写成条件式：只有在 draft 与当前策略的分布距离被持续压住、且 draft 权重显存不侵蚀 KV 池容量的前提下，代码与格式化输出类请求才能兑现 2–3 倍 decode 吞吐；一旦同步链路带宽或显存容量成为约束，规模上限即被锁死，此时应退回不改变 decode 循环的加速路径，而不是继续加大 γ 硬扛。</p>\n<h3 id=\"alg-speculative-rollout-draft-sec-21\">二十一 · 请求形态：长CoT才是配方的主菜</h3>\n<p>投机采样在rollout里的收益不是均匀分布的，它高度依赖请求的decode长度分布。机制上，draft-verify循环每轮固定付出一次目标模型前向（验证γ个候选）加γ次draft自回归，换回的是E[ tokens/step ]个被接受的token。当序列很短（几十到一两百token），固定开销占比高，验证前向的启动延迟、块表更新、logprob记录摊到少量token上，单位token成本反而上升。真正吃到红利的是长CoT样本：数千token的推理链，decode阶段逐token串行，HBM带宽受限而算力闲置，投机采样把“每步一个token”的带宽瓶颈步变成“每步多个token”的算力密集步，正好填上闲置的算力。</p>\n<p>因此负载配方的第一条判断是：把投机采样挂在长输出请求上，而不是全量请求上。工程上按请求的max_len或历史长度分桶，只对预期输出超过某个阈值的请求启用draft-verify路径，短请求走原生decode。代价是调度器要多维护一条分流逻辑与两套decode循环，但换来的是短请求不被固定开销拖累、长请求吃满加速比。若不分流，混合负载下短请求的尾延迟会被拉高，而长请求的收益被平均掉，整体rollout样本吞吐的提升远小于2–3倍这个量级。</p>\n<p>长度分布还有第二层影响：接受率沿序列位置漂移。CoT开头往往是格式化引导语、模板化推理框架，draft极容易猜中；中段进入具体计算与代码，接受率仍高；尾段结论部分措辞发散，接受率下滑。这意味着一轮γ个候选的期望接受长度并非常数，负载配方要允许γ随位置或随请求类型调整，而不是全局固定一个γ。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-22\">二十二 · 批大小与continuous batching的耦合</h3>\n<p>投机采样与continuous batching不是简单叠加。每轮验证是一次对γ个候选的并行前向，它在批维度上占的slot不是1而是γ（或按实现折算的等效计算量），而draft自回归又是γ次小批前向。批大小B下，一轮循环的目标模型计算量约为B×γ个token位置的验证，draft侧为B×γ次串行小步。批越大，验证前向的算力利用率越高，draft侧的串行开销越容易被掩盖；批越小，draft的γ次串行前向成为主导，投机采样退化为“用小模型拖慢大模型”。</p>\n<div class=\"formula\">$$\\text{effective throughput} \\approx \\frac{B\\cdot \\mathbb{E}[\\text{tokens/step}]}{T_{\\text{verify}}(B,\\gamma) + \\gamma\\cdot T_{\\text{draft}}(B)}$$</div>\n<p>这个式子说明配方的核心是让分母里的γ·T_draft(B)相对T_verify(B,γ)可忽略：要么提高B把T_verify摊薄，要么用Medusa/EAGLE头把γ次串行压成一次并行（头本身是并行预测多个位置的），要么减小γ。三者是互相替代的旋钮。工程判断是：在显存允许的前提下优先抬B，因为验证前向在Blackwell上对批维度不敏感（算力闲置正是投机采样要填的坑），而draft串行步对批维度敏感度低、对γ线性敏感。</p>\n<p>代价出现在显存侧：每轮要为γ个候选预留KV写入位置与验证用的中间激活，被拒绝候选的KV必须丢弃。批越大、γ越大，瞬时KV占用越高，块表翻新越频繁。长CoT样本下KV池本就吃紧，若块表一致性没保证，被拒候选的无效块会累积占用KV池容量，直接压缩可并发请求数——这是批大小配方里最隐蔽的吞吐杀手。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-23\">二十三 · 并发结构与接受率的相互塑造</h3>\n<p>并发数不只是吞吐旋钮，它反过来影响接受率的统计性质。高并发下每条请求的draft模型在同一批次里被复用，draft的采样温度、top-p等参数若与目标模型不一致，接受率会系统性偏低；更关键的是，RL训练早期策略分布漂移大，draft与当前策略不匹配，接受率骤降，此时提高并发只会把负收益放大——加速比低于1时，并发越高，浪费的验证算力越多。</p>\n<p>负载配方因此需要一个接受率哨兵：按滑动窗口统计每类请求的实际接受token数/候选数，低于阈值就把该请求类型切回原生decode，或触发draft重训/蒸馏。这是把“负载不对时会发生什么”变成可观测、可回退的工程动作，而不是等吞吐报表出来才发现rollout变慢。哨兵本身的代价很小（只读计数），但它要求rollout引擎在decode循环里保留每轮的候选数与接受数，这与记录每token logprob供重要性采样是同一批埋点。</p>\n<p>并发与γ还有一层耦合：γ越大，单轮验证的算力占用越像一次小prefill，高并发下验证批次会挤占prefill资源，尤其在预填/解码共享同一引擎时。配方上要么给验证路径预留算力配额，要么在并发高峰自动降γ。降γ的代价是期望接受长度下降，但换来的是验证批次不排队，尾延迟可控。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-24\">二十四 · 负载不对时的三种崩法</h3>\n<p>第一种是短请求混入：固定开销主导，单位token成本上升，表现为整体吞吐不升反降。第二种是策略漂移：draft与当前策略不匹配，接受率骤降，加速比低于1，rollout吞吐反而下降——这是RL早期最典型的负收益场景，且它不会报错，只会让训练样本产出变慢。第三种是KV碎片：被拒候选KV丢弃时块表不一致，无效块累积，长CoT样本下KV池容量被无效块占用，可并发数被动下降，形成“越加速越挤”的恶性循环。</p>\n<p>三种崩法的共同点是它们都藏在平均指标背后。配方上要用分桶指标而不是全局平均：按请求长度桶、按请求类型（代码/格式化/自由文本）、按策略更新轮次分别看接受率与单位token时延。代码与格式化输出接受率高，是投机采样的甜点区；自由文本与高温度采样接受率低，应排除在draft-verify路径外。这个分流判断本身就是负载配方的一部分，而不是部署后的调优。</p>\n<p>还有一个隐性代价：draft模型随策略更新频繁重训或蒸馏，rollout与训练的权重同步链路多一份模型，显存与同步开销增加。同步滞后会进一步降低接受率，形成“漂移→低接受率→更多重训→更多同步开销”的回路。配方上要把同步频率与接受率哨兵联动，而不是固定周期重训。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-25\">二十五 · 配方表：把判断落成可执行的分流</h3>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>γ建议</th><th>批组织</th><th>预期结果</th></tr></thead><tbody>\n<tr><td>长CoT、代码/格式化输出</td><td>较大γ，按位置可调</td><td>大B，验证优先占算力</td><td>decode吞吐提升2–3倍量级</td></tr>\n<tr><td>长CoT、自由文本、高温采样</td><td>小γ或不启用</td><td>常规continuous batching</td><td>避免负收益，保尾延迟</td></tr>\n<tr><td>短请求（数十至百token）</td><td>不启用</td><td>原生decode</td><td>不被固定开销拖累</td></tr>\n<tr><td>策略漂移期（RL早期）</td><td>哨兵触发降γ/关闭</td><td>按桶回退</td><td>防止加速比低于1</td></tr>\n</tbody></table>\n<p>这张表的每一行都对应一个具体机制决策：γ决定单轮验证的算力形态，B决定验证前向的摊薄程度，哨兵决定何时回退。配方不是静态参数，而是随接受率统计与策略更新轮次动态调整的控制回路。工程上把它实现为rollout引擎里的一条策略路由：请求进队时按长度与类型打标，decode循环按标选择路径，哨兵按桶统计并改写路由表。</p>\n<p>最后落在KV这一环：无论γ与B怎么配，被拒候选KV的丢弃必须与块表更新在同一原子步内完成，否则长CoT样本下碎片累积会先于接受率问题暴露。配方表里“预期结果”一列之所以只写定性量级，是因为实际加速比由接受率与批组织共同决定，而这两个量在策略漂移期是时变的——把哨兵和块表一致性做对，比把γ调到一个漂亮数字更重要。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-26\">二十六 · 负载配方：什么样的请求才配得上投机采样</h3>\n<p>投机采样在 rollout 里的收益不是无条件成立的，它本质上是一次“用额外算力换串行深度缩减”的交易，而交易是否划算，完全由负载形态决定。合适的请求形态是长 CoT 样本：单条序列数千 token、decode 阶段逐 token 串行、HBM 带宽受限而 SM 算力闲置。在这种形态下，目标模型每步只搬一次权重却只产出 1 个 token，带宽利用率被序列长度摊薄得极差；而投机采样把 γ 个候选塞进同一次前向，等于把这次权重搬运摊到最多 γ+1 个 token 上，正好命中“带宽瓶颈、算力富余”的病根。反过来，短请求（几十到几百 token 就 EOS）、高并发小批、prefill 占比高的负载，decode 串行开销本来就不是主导项，投机采样的验证前向反而在关键路径上多加了一次 draft 自回归，收益被固定开销吃掉。</p>\n<p>批大小与长度分布共同决定每轮验证的有效 token 数。continuous batching 下每条请求各自维护候选段，验证前向把不同请求的 γ 个候选拼进一个批次，因此批越大、序列越长，单次前向的算力填充越饱满，γ 的边际成本越低。用接受率 α 与候选长度 γ 估算每轮期望产出：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>第一项说明 γ 不是越大越好：α 偏低时，α^{γ+1} 迅速衰减，期望产出趋近于 1/(1−α) 的天花板，继续加大 γ 只是让 draft 自回归的串行链变长；第二项说明 draft 成本 c_draft 相对目标模型 c_target 的比值直接进分母。工程判断是：α 高（代码、结构化/格式化输出、模板化推理步骤）时取较大 γ 划算，α 中等时 γ 应压到 3–5 量级，让验证前向的并行度与 draft 串行链取得平衡。长度分布上，若样本长度方差极大，长尾样本会长期占据 KV 与批槽位，短样本快速周转却拿不到加速，调度器需要按剩余 max_len 与已生成长度做优先级分层，避免长 CoT 把批填满后 γ 验证的收益被少数请求独吞。</p>\n<p>负载不对时的失效是连锁的。RL 训练早期策略分布漂移大，draft 与当前策略不匹配，α 骤降，加速比可能低于 1——rollout 吞吐不升反降，因为每条请求都多背了一次 draft 前向和一次验证前向的固定开销，而接受的 token 寥寥。更隐蔽的代价在显存与同步：draft 模型（或 Medusa/EAGLE 头）与目标模型共享 tokenizer 与 KV 布局，但权重同步链路多一份模型，同步滞后会进一步压低 α，形成“越训越慢”的正反馈；被拒绝候选的 KV 必须按块表一致地丢弃，否则长 CoT 下 KV 碎片累积，KV 池容量被无效块占用，直接压缩可并发批大小。规模上限由此确定：受 draft 与目标模型同步链路带宽及显存容量约束，draft 不能无限大，γ 不能无限长。可操作的配方是——把投机采样限定在长 CoT、高结构化输出、批已填满的 decode 阶段；对短请求与 prefill 主导的流量走原路径；并以实测 α 作为开关信号，α 跌破阈值即回退到逐 token 解码，把负收益挡在 rollout 关键路径之外。</p>\n<h3 id=\"alg-speculative-rollout-draft-sec-27\">二十七 · 硬件档位：按 draft 与 target 的显存比切三档</h3>\n<p>部署投机采样 rollout 的第一件事不是选框架，而是确定 draft 模型与目标模型能否同卡共存。SM100/SM103 的 HBM 容量决定了三个可行档位，档位选择直接改变同步链路形态。</p>\n<ul>\n<li><b>同卡共驻档</b>：draft 与 target 放在同一张 B200/B300 上，draft 用剩余显存与算力切片。优点是权重同步走同一 HBM 域，无需跨卡搬运；代价是 target 的 KV 池被 draft 权重挤占，长 CoT 样本（数千 token）下 KV 块数减少，continuous batching 的并发批上限下降。</li>\n<li><b>同节点分卡档</b>：draft 独占一张小卡或 target 节点内的空闲 GPU，两者经 NVLink 5 互联。同步走 NVLink，带宽足够支撑每轮策略更新后的 draft 重蒸馏权重下发；代价是多一份模型驻留，节点显存利用率下降。</li>\n<li><b>跨节点档</b>：draft 与 target 分处不同节点，同步经 NCCL/NIXL 走网络。仅在 target 规模大到单节点放不下时采用，同步延迟直接进入接受率衰减链路。</li>\n</ul>\n<p>判断准则是一个显存比：设 target 权重加 KV 池需求为 $M_t$，draft 权重为 $M_d$，则同卡共驻要求 $M_t + M_d \\le$ 单卡 HBM，且留给 KV 池的余量必须覆盖最长 CoT 样本的块需求。工程上把 draft 权重控制在 target 的百分之几量级，才能让同卡档成立；EAGLE/Medusa 头天然满足这一约束，独立小 draft 模型则常被推到分卡档。</p>\n<p>代价落在带宽上：同卡档中 draft 自回归生成 γ 个候选时与 target 验证共享 HBM 带宽，draft 的逐 token 解码本身就是带宽受限操作，会与 target 的验证前向争抢带宽，实际加速比低于公式给出的理论上界。分卡档把这份带宽竞争移出 target 卡，但引入 NVLink 上的候选 token 与概率传输。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-28\">二十八 · 并行拓扑：验证前向的切分与 draft 的放置</h3>\n<p>target 的验证前向一次处理 γ 个候选位置，其并行切分方式决定单轮验证延迟。Blackwell 上可用的切分有三类，选择取决于 γ 与批大小的乘积是否足以填满 SM。</p>\n<ul>\n<li><b>张量并行（TP）</b>：把 target 的权重切到多卡，每卡算部分和。γ 个候选位置作为序列维一起进入，TP 通信量随 γ 线性增长，适合 γ 较大、单卡放不下 target 的场景。</li>\n<li><b>2-SM MMA 与 tcgen05 路径</b>：验证前向的注意力与 MLP 走 Blackwell 的双 SM 协作矩阵乘，TMEM 承载累加器。γ 个候选的 verify 是典型的“短序列、多位置并行”形态，2-SM MMA 能把每对 SM 的吞吐拉满，但要求 γ 与批维对齐到 MMA 的 tile 形状，否则尾块浪费。</li>\n<li><b>数据并行（DP）复制</b>：target 整体复制多份，每份服务不同请求批次，draft 按请求就近放置。适合 draft 接受率稳定、需要横向扩吞吐的在线服务，但每份复制都带一份完整 KV 池，显存代价最高。</li>\n</ul>\n<p>draft 的放置要与 target 的切分对齐：若 target 走 TP，draft 应复制到每个 TP rank 或只在 rank 0 上生成候选再广播，前者省一次广播但多份 draft 权重，后者省显存但每轮多一次集合通信。工程判断是——当 γ 小、候选生成快时选广播，当 γ 大、draft 自回归本身耗时显著时选复制。</p>\n<div class=\"formula\">$$\\text{verify latency} \\approx \\frac{\\gamma \\cdot B \\cdot L_{\\text{ctx}} \\cdot d}{F_{\\text{eff}}} + T_{\\text{comm}}(\\text{TP})$$</div>\n<p>其中 $B$ 为批大小，$L_{\\text{ctx}}$ 为上下文长度，$d$ 为模型宽度，$F_{\\text{eff}}$ 为有效算力。公式说明：γ 增大提升每轮产出 token 数，但验证延迟随 γ 线性上升；存在一个 γ 使 tokens/step 与单步延迟的比值最优，这个 γ 由接受率 α 与 draft 成本 $c_{\\text{draft}}/c_{\\text{target}}$ 共同决定，而非固定值。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-29\">二十九 · 量化方案：draft 与 target 的精度不必一致</h3>\n<p>投机采样的输出无偏性只依赖接受规则与残差重采样，不要求 draft 与 target 使用同一精度。这一性质给量化部署留出空间：target 走 NVFP4/FP8 以压权重带宽，draft 走更高精度以保证候选概率质量，或反过来。</p>\n<ul>\n<li><b>target NVFP4、draft FP8/FP16</b>：target 的验证前向是带宽受限的，NVFP4 把权重带宽压到四分之一，验证延迟下降；draft 保持较高精度，使 $p_{\\text{draft}}$ 更接近真实分布，接受率不因 draft 量化而塌陷。这是长 CoT rollout 的推荐组合。</li>\n<li><b>两者同精度</b>：实现最简单，KV 布局与 tokenizer 完全共享，但 target 量化误差会进入 $p_{\\text{target}}$，接受规则仍无偏，只是接受率对量化噪声更敏感。</li>\n<li><b>draft 量化、target 高精度</b>：仅在 target 必须保精度（如数值敏感任务）时采用，draft 量化误差直接压低接受率，加速比受损。</li>\n</ul>\n<p>关键机制在于接受概率的计算：$p_{\\text{accept}}=\\min(1, p_{\\text{target}}(x)/p_{\\text{draft}}(x))$ 中两个概率来自不同精度的前向，量化噪声会让比值在边界处抖动。工程上对 draft 的概率输出做温度与 top-k 截断后再喂入接受规则，可减少因 draft 概率尾部噪声导致的误拒绝。代价是 target 的 NVFP4 权重需要校准，校准数据应覆盖当前策略的 rollout 分布，否则量化误差在策略漂移后放大。</p>\n<p>显存收益直接：target 权重压到 NVFP4 后，同卡共驻档的 KV 池余量显著增加，长 CoT 样本的块容量上升，continuous batching 可容纳更多并发请求。这条收益与 draft 的显存占用叠加，是同卡档能否成立的决定因素。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-30\">三十 · KV 策略：只写接受段与块表一致性</h3>\n<p>投机采样不改变 prefill/KV 组织，但在 decode 循环内对 KV 写入提出了更细的粒度要求：每轮只有接受段加一个重采样 token 需要增量写入，被拒绝候选的 KV 必须丢弃且不能污染块表。</p>\n<ul>\n<li><b>接受段增量写</b>：验证前向会为 γ 个候选位置算出 KV，但只有前 $k$ 个被接受（$k \\le \\gamma$，首个拒绝位置前）。工程实现是验证时把候选 KV 写入临时块，接受后把临时块的前 $k$ 个 slot 提交到序列的正式块表，其余 slot 标记为空闲。这样避免了对整段 γ 的重复计算。</li>\n<li><b>块表一致性</b>：被拒绝候选的临时块必须归还到空闲池，且归还前清除引用计数，否则长 CoT 样本下无效块累积，KV 池容量被逐步占用。这是失败模式中明确列出的风险点，需在 decode 循环的每轮结束时做一次块表校验。</li>\n<li><b>前缀共享的兼容</b>：若 rollout 引擎同时使用前缀 KV 共享，接受段的块提交要遵循共享块的引用计数规则，避免共享前缀被误释放。这一层与分页 KV 批量 rollout 的块管理共用同一套分配器。</li>\n</ul>\n<p>代价体现在块分配器的锁竞争上：continuous batching 下多条请求并发做临时块申请与提交，分配器成为热点。缓解方式是按 SM 或按请求分片分配器，把临时块的生命周期限制在单轮验证内，减少跨请求的块表交互。</p>\n<div class=\"formula\">$$\\text{KV waste per round} = (\\gamma - k)\\cdot s_{\\text{slot}},\\quad \\text{pool pressure} \\propto \\sum_{\\text{rounds}}(\\gamma - k)$$</div>\n<p>其中 $s_{\\text{slot}}$ 为单 token KV 的字节数。公式说明拒绝比例越高，临时块的周转压力越大；在策略漂移导致接受率骤降的早期训练阶段，$\\gamma - k$ 接近 γ，KV 池的无效占用会显著上升，这也是加速比可能低于 1 时显存侧的连带代价。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-31\">三十一 · 调度参数：γ、批大小与同步节奏的联合整定</h3>\n<p>调度层要整定的参数有四个：γ、continuous batching 的批上限、draft 重蒸馏的同步节奏、以及接受率触发的降级阈值。它们不是独立可调的，联合整定才能避免负收益。</p>\n<ul>\n<li><b>γ 的自适应</b>：按当前策略的滑动接受率 α 调整 γ。α 高时增大 γ 提升每轮产出；α 低时减小 γ，因为大 γ 下被拒绝的候选 KV 浪费与验证延迟同时上升。整定目标是使 $\\mathbb{E}[\\text{tokens/step}]/(1+\\gamma c_{\\text{draft}}/c_{\\text{target}})$ 最大化，工程上用近期接受率估计 α 后查表选 γ。</li>\n<li><b>批上限与 γ 的耦合</b>：验证前向的计算量正比于 $B \\cdot \\gamma$，批上限提高会挤压 γ 的可用空间。长 CoT 样本的 decode 阶段应优先保 γ 而非保批，因为单请求的串行长度是主导延迟；短样本则可反向取舍。</li>\n<li><b>同步节奏</b>：draft 随策略更新重蒸馏的频率要与接受率衰减速度匹配。同步滞后会降低接受率，同步过频则占用 target 的算力与带宽。工程判断是以接受率的下降斜率触发重蒸馏，而非固定步数。</li>\n<li><b>降级阈值</b>：当滑动接受率低于某阈值时，rollout 引擎切回无 draft 的逐 token 解码，避免负收益。阈值由 $c_{\\text{draft}}/c_{\\text{target}}$ 决定：draft 成本越高，阈值越高。</li>\n</ul>\n<p>调度参数的代价是控制回路的开销：接受率统计、γ 查表、降级切换都在 decode 循环内，若每轮都做会引入额外延迟。实现上把统计窗口放在请求级而非轮级，每若干轮更新一次 γ，把控制开销摊薄。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-32\">三十二 · 一个可复现的配置思路</h3>\n<p>把上述五节收束成一条可复现的配置路径，按顺序决策，每步都有明确的判据与回退。</p>\n<ul>\n<li><b>第一步定档位</b>：测 target 权重加最长 CoT 样本 KV 需求，若加 draft 权重后仍能留出足够 KV 余量，选同卡共驻；否则选同节点分卡，draft 走 NVLink 同步。</li>\n<li><b>第二步定量化</b>：target 上 NVFP4，draft 保 FP8/FP16，用当前策略的 rollout 样本做 target 校准；若接受率对量化敏感，回退 target 到 FP8。</li>\n<li><b>第三步定拓扑</b>：γ 与批大小的乘积能填满 SM 时走 2-SM MMA 路径并对齐 tile；target 单卡放不下时走 TP，draft 按 γ 大小选复制或广播。</li>\n<li><b>第四步定 KV</b>：临时块加接受段提交的写入路径，每轮结束做块表校验，与分页 KV 分配器共用空闲池。</li>\n<li><b>第五步定调度</b>：以滑动接受率驱动 γ 自适应，设降级阈值切回逐 token 解码，重蒸馏由接受率斜率触发。</li>\n</ul>\n<p>这条路径的验证方式是：在目标硬件上跑一段真实 rollout 负载，记录每轮接受段长度 $k$、γ、验证延迟与 KV 池占用，确认加速比稳定大于 1 且块表无累积泄漏。若加速比在策略更新后跌破 1，先查同步节奏是否滞后，再查 γ 是否过大导致拒绝浪费，最后查量化校准是否失配。配置的可复现性来自每一步都有可观测的判据，而不是依赖经验常数。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-33\">三十三 · 配方边界：接受率悬崖、显存水位与同步链路</h3>\n<p>这套配方可复现的关键不在参数本身，而在三个边界条件同时成立：draft 与目标模型共享 tokenizer 与 KV 布局、rollout 引擎只在 decode 循环内改动、块表在被拒候选 KV 丢弃时保持强一致。硬件档位上，draft 模型与目标模型必须同处一个 NVLink 域，否则每轮 γ 个候选的验证前向要跨节点搬运激活，γ 越大，搬运开销越接近目标模型单次前向的收益。量化方案上，draft 侧宜与目标侧同精度族（如两侧同为 FP8 或同为 NVFP4），混用会引入概率比 $p_{\\text{target}}/p_{\\text{draft}}$ 的系统性偏置，使接受判定偏离无偏前提。KV 策略上，被拒候选的 KV 必须整块回滚而非原地覆盖，长 CoT 样本下块表不一致会让 KV 池被无效块占用，容量水位随步数单调抬升。</p>\n<p>失效条件集中在接受率悬崖。RL 早期策略漂移大，draft 与当前策略不匹配时 $\\alpha$ 骤降，加速比公式 $\\text{speedup} \\approx \\mathbb{E}[\\text{tokens/step}]/(1+\\gamma c_{\\text{draft}}/c_{\\text{target}})$ 的分母被 draft 开销主导，结果低于 1，rollout 吞吐反而下降。工程判断是设接受率下限阈值：连续若干轮 $\\alpha$ 低于阈值即退回纯目标模型 decode，并把 draft 重训或蒸馏排进权重同步链路。同步滞后本身是二次惩罚——draft 越旧，$\\alpha$ 越低，重训越频繁，显存与同步开销越高。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>draft 放置</th><th>γ 取值倾向</th><th>主要代价</th></tr></thead><tbody><tr><td>同卡共置</td><td>与目标模型同 GPU，分时复用</td><td>小 γ，省显存</td><td>draft 前向挤占目标模型算力</td></tr><tr><td>同节点分卡</td><td>NVLink 域内独立卡</td><td>中大 γ</td><td>多一份模型显存与权重同步带宽</td></tr><tr><td>跨节点</td><td>不推荐用于高 γ</td><td>仅小 γ</td><td>激活搬运延迟压过验证收益</td></tr></tbody></table>\n<p>调度参数上，continuous batching 的批内每条请求独立推进 γ 轮验证，批大小受 draft 与目标两份权重的显存水位约束，而非单模型时的 KV 池上限。长 CoT 样本（数千 token）下，γ 应随已生成长度分段调整：前缀阶段接受率高可放大 γ，进入高熵推理段则收缩，避免无效候选拖长每步时延。可复现的配置思路是固定 tokenizer 与 KV 布局、锁定同精度族、以接受率阈值作为唯一回退开关，其余参数按显存水位反推。</p>\n<h3 id=\"alg-speculative-rollout-draft-sec-34\">三十四 · 显存账：draft 模型不是免费的</h3>\n<p>投机采样在 rollout 侧的第一笔系统代价是显存。目标模型之外，draft 模型（或 Medusa/EAGLE 头）必须常驻同一张卡或同一组卡上，因为 decode 循环里 draft 自回归与 target 并行验证是交替进行的，权重换入换出会把收益全部吃掉。以 GB200 NVL72 单节点为例，目标模型权重、draft 权重、KV 池三者共享 HBM；draft 权重虽然小，但它挤占的是 KV 池的可用容量，而长 CoT 样本（数千 token）的 KV 占用随批内序列长度线性增长，KV 池一旦被压缩，continuous batching 的批大小上限就下降，吞吐直接受损。更隐蔽的一笔是权重同步链路：draft 需随策略更新频繁重训或蒸馏，训练侧的更新权重必须跨 NVLink 5 送到 rollout 引擎，这条链路上多一份模型就意味着多一份显存驻留与多一份同步缓冲。工程判断是：draft 权重的显存开销应按“KV 池容量折损”来核算，而不是按参数字节数核算——在 KV 池接近饱和的配置下，多一个 draft 模型可能让批大小从数十降到个位数。</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{avail}} = \\text{HBM} - W_{\\text{target}} - W_{\\text{draft}} - W_{\\text{act}} - W_{\\text{comm}}$$</div>\n<p>其中 $W_{\\text{comm}}$ 是同步缓冲与 NCCL/NIXL 通信缓冲。规模上去以后，最先崩的往往不是算力而是这个减法：$W_{\\text{draft}}$ 与 $W_{\\text{comm}}$ 同时增长，$\\text{KV}_{\\text{avail}}$ 缩小，批大小下降，decode 阶段的 HBM 带宽利用率反而更差——因为每步并行验证 γ 个候选需要读的 KV 与权重是固定的，批越小，摊薄在每 token 上的带宽开销越大。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-35\">三十五 · 带宽账：γ 个候选的并行验证读什么</h3>\n<p>decode 阶段本质是 HBM 带宽受限而算力闲置，投机采样把 γ 次串行前向压成一次并行验证，改变的是带宽访问的粒度而不是总量。目标模型对 γ 个候选做一次前向时，需要为每个候选位置读取该位置的 KV（候选 token 尚未写入 KV，验证用的是前缀 KV 加候选位置的临时激活），因此一次验证的 KV 读取量约为 $\\gamma \\cdot$ 单 token KV 字节数，但权重只读一遍——这正是加速的来源：权重读取被 γ 个候选摊薄。若把单 token decode 的带宽代价记为 $B_w + B_{kv}$（权重与 KV），则投机采样每轮验证的带宽代价约为 $B_w + \\gamma B_{kv}$，产出 $\\mathbb{E}[\\text{tokens/step}]$ 个 token，于是每 token 带宽代价为 $(B_w + \\gamma B_{kv})/\\mathbb{E}[\\text{tokens/step}]$。当接受率高、$\\mathbb{E}[\\text{tokens/step}]$ 接近 γ 时，权重项被摊薄到接近零，带宽收益显著；当接受率骤降、$\\mathbb{E}[\\text{tokens/step}]$ 趋近 1 时，每 token 代价反而高于朴素 decode，这就是加速比低于 1 的带宽层面的解释。</p>\n<div class=\"formula\">$$\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>公式中 $c_{\\text{draft}}/c_{\\text{target}}$ 是 draft 单步代价与 target 单步代价之比，它同时包含带宽与算力。工程上要盯的是这个比值随批大小的变化：批大时 target 前向的权重读取被批内多条请求摊薄，$c_{\\text{target}}$ 相对下降，而 draft 自回归是逐 token 串行、批内并行度低，$c_{\\text{draft}}$ 摊薄得慢，于是 γ 增大时 draft 的相对代价上升。规模上去以后，第二个先崩的点就在这里：批越大，draft 的串行自回归越成为带宽与调度的瓶颈，γ 的边际收益递减。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-36\">三十六 · 通信账：同步链路与拒绝候选的 KV 一致性</h3>\n<p>投机采样本身不改变 prefill/KV 组织，也不引入张量并行之外的新通信模式，但它把两条通信链路推到前台。第一条是权重同步：draft 随策略更新频繁重训或蒸馏，同步滞后会进一步降低接受率，形成“同步慢→接受率低→加速比低→rollout 更慢→策略更新更慢”的正反馈。在 NVL72 这种机架级域内，NVLink 5 的带宽足以承载权重广播，但同步的代价不只是字节数，而是同步点的时序——rollout 引擎必须在某个 batch 边界停下等待新权重，这段等待在长 CoT 样本下会被放大，因为单条样本的 decode 循环可能跨越数千 token、持续很久。第二条是拒绝候选的 KV 一致性：被拒绝的候选 KV 丢弃需保证块表一致，否则 KV 碎片累积，长 CoT 样本下 KV 池容量被无效块占用。分页 KV 的块表在验证后被回滚，若回滚与块分配不在同一临界区，跨请求的块复用会出现空洞，表现为 KV 池“看起来还有空块但分配失败”。这是规模上去以后第三个先崩的点：不是带宽也不是显存总量，而是块表一致性维护带来的分配器抖动。</p>\n<ul>\n<li>同步点应绑在 batch 边界而非请求边界，避免单条长样本拖住整批权重切换。</li>\n<li>拒绝回滚要与块分配共用同一版本号或纪元计数，块表回滚失败即触发该请求的 KV 重建而非静默复用。</li>\n<li>draft 权重同步走独立通道，避免与 KV 传输争用同一 NIXL 路径。</li>\n</ul>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-37\">三十七 · 功耗与尾延迟：γ 放大的是方差不是均值</h3>\n<p>投机采样对尾延迟的影响是非对称的。均值上，接受率高时每步产出多个 token，decode 时延下降；但方差被 γ 放大——一轮验证中若第一个候选即被拒绝，本轮只产出一个重采样 token，且这一轮付出了 draft 自回归 γ 步加 target 一次前向的代价，单步时延反而高于朴素 decode。长 CoT 样本的尾延迟由最慢的那一轮决定，而最慢的一轮往往出现在策略分布漂移、接受率骤降的样本上。对 SLO 而言，rollout 样本吞吐与 decode 时延要分开看：吞吐看均值，SLO 看尾部分位数。功耗层面，draft 自回归是低并行度、低利用率的串行循环，它在单位时间内做的有效计算少，但 GPU 仍处于活跃状态，能效比（每 token 焦耳）在接受率低时显著恶化；B200/B300 的功耗上限固定，draft 与 target 交替占用 SM 会让功耗在两种模式间摆动，电源管理的响应速度跟不上毫秒级的 decode 循环切换，实测表现为功耗墙下的频率抖动。</p>\n<table class=\"mini\"><thead><tr><th>规模上升时的压力点</th><th>先崩的信号</th><th>工程对策</th></tr></thead><tbody><tr><td>draft 权重 + 同步缓冲挤占 KV 池</td><td>批大小上限下降、KV 分配失败率上升</td><td>按 KV 折损核算 draft 预算，draft 与 target 分卡放置</td></tr><tr><td>批大后 draft 串行自回归摊薄慢</td><td>γ 增大但每 token 带宽代价不降</td><td>按批大小自适应调 γ，而非固定 γ</td></tr><tr><td>权重同步滞后</td><td>接受率随训练步数下滑</td><td>同步绑 batch 边界、独立通道、异步预取</td></tr><tr><td>拒绝回滚块表不一致</td><td>KV 碎片累积、长样本 OOM</td><td>回滚与分配同纪元，失败即重建</td></tr><tr><td>尾延迟方差放大</td><td>p99 decode 时延高于朴素 decode</td><td>按样本难度路由，低接受率样本退回朴素 decode</td></tr></tbody></table>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-38\">三十八 · 规模上限：同步链路带宽与显存容量先约束谁</h3>\n<p>适用边界写明规模上限受 draft 与目标模型同步链路带宽及显存容量约束。这两条约束谁先起作用取决于部署形态：单卡共存时显存先崩，因为 draft 权重与 KV 池在同一 HBM 上做减法；分离部署时同步链路先崩，因为 draft 在另一组卡上，每轮 decode 循环都要跨卡取 draft 权重或 draft 侧 KV，跨卡往返时延叠加在每轮验证上，γ 越大往返越频繁。GB300 NVL72 的机架级域内带宽足以支撑 draft 与 target 分置，但分置后 draft 侧的批内并行度更低，$c_{\\text{draft}}$ 上升，公式里的分母变大，加速比被吃掉。工程判断是：当接受率稳定在高位时，把 draft 与 target 分置、用机架带宽换 KV 池容量是划算的；当接受率随训练漂移、需要频繁重训 draft 时，同步链路的时序代价超过显存收益，应回到共存部署并把 γ 调小。</p>\n<p>还有一个容易被忽略的规模效应：rollout 引擎记录每 token 的 logprob 供训练侧重要性采样使用，投机采样一轮产出多个 token，logprob 的记录与回传是批量化的，但被拒绝候选的 logprob 也要参与残差重采样的计算，这部分中间量在批大时占用可观的临时缓冲。它与 KV 池争的是同一块 HBM，在长 CoT 样本、大批、高 γ 三者叠加时，临时缓冲的增长速度超过 KV 的增长速度，成为显存账上最先溢出的项。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-39\">三十九 · 吞吐归因：把加速比拆成可观测的量</h3>\n<p>要把“规模上去以后哪里先崩”变成可运维的判断，需要把加速比拆成可观测的量而不是只看端到端 tokens/s。建议在 rollout 引擎里埋三个计数器：每轮实际接受 token 数（即 $\\mathbb{E}[\\text{tokens/step}]$ 的在线估计）、每轮 draft 自回归耗时与 target 验证耗时之比（$c_{\\text{draft}}/c_{\\text{target}}$ 的在线估计）、以及块表回滚失败次数。三者分别对应公式的分子、分母与失败模式。当分子下滑而分母不变，是接受率问题，归因到策略漂移与同步滞后；当分母上升而分子不变，是 draft 相对代价问题，归因到批大小与 γ 配置；当回滚失败次数上升，是 KV 碎片问题，归因到块表一致性。吞吐的容量规划应按“有效接受 token 数 / 每轮墙钟时间”做，而不是按 draft 或 target 单侧的利用率做——单侧利用率高恰恰可能是 draft 串行自回归在空转。</p>\n<div class=\"formula\">$$\\text{吞吐}_{\\text{eff}} = \\frac{\\sum_{\\text{轮}} \\text{accepted}_i}{\\sum_{\\text{轮}} (t_{\\text{draft},i} + t_{\\text{verify},i} + t_{\\text{sync},i})}$$</div>\n<p>分母里显式加上 $t_{\\text{sync}}$ 是把权重同步的时序代价计入吞吐，避免在同步频繁的配置下高估容量。规模上去以后，这个式子的三个分量谁先膨胀，就决定了该扩哪一侧：$t_{\\text{draft}}$ 膨胀说明 draft 侧并行度不足、该加批或换更轻的头；$t_{\\text{verify}}$ 膨胀说明 target 侧 KV 读取被批大小或 γ 拖累、该调 γ 或缩批；$t_{\\text{sync}}$ 膨胀说明同步链路成为主约束、该改部署形态。把这三个量做成 rollout 引擎的常驻指标，比事后调参更能定位规模上限的真实位置。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-40\">四十 · 规模上去以后，先崩的是同步链路而不是算力</h3>\n<p>把投机采样放进 RL rollout，系统代价的重心并不在目标模型的验证前向上。验证是并行的一次前向，算力开销相对可控；真正随规模恶化的是 draft 与目标模型之间的权重同步链路。每轮策略更新后 draft 都要重训或蒸馏，rollout 侧就多出一份模型权重、一份优化器状态搬运和一条跨节点广播路径。同步滞后直接压低接受率 α，而 α 在期望 token 数里是幂次项：$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$，α 从高位滑落时该式迅速趋近 1，加速比随之跌破 1。规模越大，同步窗口越长，α 的滞后越明显，这是负收益的第一触发点。</p>\n<p>显存与带宽的挤压在长 CoT 样本上更尖锐。被拒绝候选的 KV 必须丢弃，块表要保证一致，否则数千 token 的样本会把 KV 池逐步啃出碎片，有效容量被无效块占住。draft 模型自身也占一份权重与一份 KV 布局，虽然与目标共享 tokenizer 和 KV 布局，但容量是实打实翻倍的。以 γ 个候选并行验证为例，每轮验证的带宽代价近似正比于 γ 倍的激活读写，而收益只在接受段；当接受段短于 γ 的一半，带宽花在丢弃的候选上，HBM 受限的 decode 反而更堵。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>表现</th></tr></thead><tbody><tr><td>策略更新频率</td><td>权重同步链路</td><td>α 滞后，加速比 &lt; 1</td></tr><tr><td>样本长度（数千 token）</td><td>KV 池容量</td><td>碎片累积，无效块占用</td></tr><tr><td>γ 增大</td><td>验证带宽</td><td>丢弃候选摊薄收益</td></tr></tbody></table>\n<p>尾延迟是另一个容易被忽略的代价。continuous batching 下每条请求的接受率不同，接受率低的请求每轮只前进一两个 token，却要和接受率高的请求共享同一批验证前向，批内进度差被拉大，P99 decode 时延由最慢的那条请求决定。工程判断是：把 draft 的重训/蒸馏节奏与策略更新解耦成异步流水，用接受率的在线统计做准入——α 低于阈值时对该批请求退回纯目标模型 decode，宁可放弃 2–3 倍的名义加速，也不让同步滞后把整批 rollout 吞吐拖到 1 以下。</p>\n<h3 id=\"alg-speculative-rollout-draft-sec-41\">四十一 · 接受率塌陷：从统计信号到根因定位</h3>\n<p>投机采样在 rollout 里最危险的失败不是崩溃，而是“静默降速”：引擎仍在产出 token，但每轮验证只接受 1 个甚至 0 个候选，decode 循环退化成“draft 白跑 γ 步 + target 跑 1 步”，加速比跌破 1。按前文公式，加速比的分母里始终带着 γ·c_draft/c_target 这一项，一旦 E[ tokens/step ] 从接近 γ+1 掉到 1 附近，这一项就从“便宜的并行验证”变成纯开销。诊断的第一原则是把接受率当作一等指标暴露出来，而不是只看 tokens/s。</p>\n<p>具体机制：在 rollout 引擎的验证步骤里，逐位置记录接受指示量 a_i∈{0,1}，并按请求、按 batch、按时间窗口三个维度聚合。单请求维度给出“这条 CoT 样本的接受长度分布”，batch 维度给出“本轮 batch 的平均接受 token 数”，时间窗口维度给出“与策略版本号对齐的接受率曲线”。关键是把接受率曲线与训练侧的策略更新步数画在同一时间轴上——RL 早期策略分布漂移大，draft 与当前策略不匹配，接受率会随策略步数呈阶梯式下滑，这种形态几乎可以直接判定为“draft 落后于策略”，而非硬件或调度问题。</p>\n<div class=\"formula\">$$\\bar{A}=\\frac{1}{N}\\sum_{j=1}^{N}\\frac{\\#\\{\\text{accepted tokens in request }j\\}}{\\#\\{\\text{proposed tokens in request }j\\}},\\quad \\text{speedup}\\approx\\frac{\\bar{A}+1}{1+\\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>工程上把 $\\bar{A}$ 与理论盈亏平衡点对比：令 speedup=1 解出临界接受率，低于该值即触发告警。系统代价方面，接受率塌陷的直接代价是 decode 时延翻倍量级（每 token 需要一次完整 target 前向加一次无效 draft 前向），在长 CoT 样本（数千 token）上，单条样本的生成时间被拉长到原本的 1.5–2 倍，rollout 样本吞吐随之下降，进而拖慢整条 RL 训练流水线。具体例子：某批代码类 rollout 请求接受率从高位掉到接近零，tokens/s 只下降了三成，容易被误判为“负载波动”；但把 $\\bar{A}$ 单独打点后立刻定位到 draft 权重版本落后于 target 两个策略步，回滚 draft 到与 target 同版本后接受率恢复。这类问题靠吞吐指标是看不出来的。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-42\">四十二 · 精度问题：无偏性被破坏的三种路径</h3>\n<p>投机采样的正确性依赖逐位置接受概率 $p_{\\text{accept}}=\\min(1,p_{\\text{target}}(x)/p_{\\text{draft}}(x))$ 与拒绝处从残差分布 $(p_{\\text{target}}-p_{\\text{draft}})^{+}$ 重采样这一对操作严格配对。工程实现里破坏无偏性的路径有三条：其一，draft 与 target 的概率归一化口径不一致（例如 draft 在温度采样后重新归一化，target 用原始 logits），导致比值失真；其二，残差分布实现时对负部截断后未重新归一化，重采样分布总和不为 1，采样器静默回退到均匀分布；其三，KV 只对接受段增量写入时，若被拒绝位置的 KV 未彻底丢弃而残留到下一轮，target 前向看到的上下文与已接受前缀不一致，概率整体偏移。</p>\n<p>诊断手段是“分布对账”：对同一前缀，用小批量样本分别跑纯 target 自回归与 draft-verify 路径，比较两条路径在相同前缀下的下一 token 分布。理论上二者应完全一致（这是该算法与近似加速方法的本质区别），任何系统性偏差都指向上述三条路径之一。伪代码思路：固定前缀 P，采样 K 次首 token，统计经验分布与 target 分布的 KL 散度，散度随 K 增大应收敛到零；若收敛到非零平台，则实现有偏。系统代价：对账本身要额外跑纯 target 前向，属于离线或低频在线校验，占用少量 target 算力，但能避免“训练侧重要性采样用到有偏 logprob”这种污染训练信号的隐性代价——rollout 引擎记录的每 token logprob 直接进入重要性采样比值，偏差会被放大成策略梯度噪声。具体例子：某次改动把残差重采样换成“直接在 target 分布上重采样”，表面看接受率不变，但对账散度出现稳定平台，训练侧重要性采样权重方差明显变大，回滚该改动后恢复。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-43\">四十三 · OOM 与 KV 碎片：被拒绝候选的账要算清</h3>\n<p>投机采样在显存上的独特风险来自“候选 KV 的临时占用”。每轮 draft 生成 γ 个候选，target 并行验证时这 γ 个位置的 KV 都要先写入才能做注意力，验证后被拒绝段的 KV 必须丢弃。若块表管理按“先分配后回收”的朴素路径走，被拒绝块在回收前处于占用状态；长 CoT 样本连续数千轮验证，若回收逻辑有遗漏或延迟，KV 池会被无效块逐步蚕食，最终表现为“明明平均序列长度没变，却开始 OOM”。这与分页 KV 批量 rollout 里的碎片问题同源，但投机采样把分配/回收频率放大了 γ 倍，暴露得更快。</p>\n<p>诊断机制：给 KV 池打三本账——已分配块数、有效块数（被接受前缀实际引用）、悬空块数（已分配但无引用）。悬空块数随时间单调上升即为泄漏信号。回收路径应保证“验证结束即回收拒绝段”，并在块表里维护候选段的临时引用计数，验证完成后一次性释放。系统代价：多一本引用计数账带来每轮验证的簿记开销，但相比 OOM 导致的整批 rollout 中断（重跑整批长 CoT 样本，浪费的 target 算力远超簿记成本），这笔开销是必要的。具体例子：某部署在 γ 较大时观察到每千轮悬空块缓慢累积，定位到拒绝段回收只在“首个拒绝位置之后”执行，而首个拒绝位置本身的 KV 未纳入回收集合；修正回收边界后悬空块数归零。另需注意 draft 模型本身多一份权重，显存预算要按“target + draft + 候选 KV 峰值”三者之和规划，规模上限受 draft 与 target 同步链路带宽及显存容量约束。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-44\">四十四 · 批抖动与路由不均：continuous batching 下的接受率方差</h3>\n<p>continuous batching 把不同长度的请求混在一个 batch 里，投机采样的接受率在请求间差异极大——代码与格式化输出接受率高，自由文本与早期策略样本接受率低。若调度器按“先到先服务”组批，一个 batch 里混入大量低接受率请求，会把整批的有效 token 产出拉低，形成批级抖动：相邻两个 batch 的 tokens/step 相差数倍，tokens/s 曲线呈锯齿。更隐蔽的是路由不均：若 draft 模型部署为多副本、按请求哈希路由，而不同副本的 draft 权重版本不一致（滚动更新期间），同一策略下不同副本的接受率出现系统性差异，表现为“部分副本吞吐正常、部分副本持续低效”。</p>\n<p>诊断与治理：按请求特征（任务类型、历史接受率、当前策略步）给请求打标签，调度器做“接受率感知组批”，把高接受率请求聚批以拉高每轮有效 token 数；同时监控每个 draft 副本的接受率分布，副本间方差超过阈值即判定为版本漂移，触发副本级回滚或强制同步。系统代价：接受率感知组批牺牲少量调度公平性（低接受率请求可能等待更久），换来 batch 级 tokens/step 的提升；副本级监控需要每条请求携带 draft 版本号，增加少量元数据带宽。具体例子：滚动更新期间三个 draft 副本中一个仍持旧权重，该副本接受率显著低于其余两个，聚合看板上的整体接受率只轻微下降，但按副本拆分后立即暴露；暂停该副本流量并重同步后，批抖动消失。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-45\">四十五 · 尾延迟尖刺：长 CoT 样本的 p99 从哪来</h3>\n<p>rollout 的 SLO 关注样本吞吐与 decode 时延，但真正咬人的是 p99。投机采样的尾延迟尖刺有三个来源：其一，单条长 CoT 样本在某一轮遇到连续拒绝，γ 个候选全部被拒，该轮只前进 1 个 token 且付出了一次完整 target 前向，若这种“全拒轮”在长序列尾部密集出现，单样本生成时间被显著拉长；其二，候选 KV 峰值与 batch 内其他请求的 KV 需求叠加，触发显存压力下的调度退避；其三，draft 与 target 的权重同步在 rollout 高峰时段抢占带宽，同步窗口内 draft 前向变慢，c_draft 上升直接压低加速比。</p>\n<p>诊断机制：把每轮验证的“接受长度”作为直方图打点，重点看长度为 0 的轮次占比及其在序列位置上的分布；同时记录每轮 target 前向耗时与 draft 前向耗时的比值，该比值异常升高指向同步抢占或显存压力。治理上，对“全拒轮”密集的请求做降级——临时增大 γ 或直接切回纯 target 自回归（放弃加速但稳定时延），并把权重同步安排在 rollout 低谷窗口。系统代价：降级路径需要引擎支持逐请求切换 decode 模式，增加分支复杂度；同步窗口错峰会拉长权重生效延迟，需与训练侧策略步节奏对齐。具体例子：某长 CoT 请求在序列后段连续出现全拒轮，p99 时延明显高于中位数，引擎按“连续 k 轮全拒即切纯 target”策略处理后，该请求时延回落到正常区间，代价是这条样本放弃了投机加速。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-46\">四十六 · 监控面板与回滚闸门</h3>\n<p>把上述信号收敛成一张可执行的监控面板：一级指标是 tokens/s 与 p99 decode 时延；二级指标是 $\\bar{A}$、全拒轮占比、悬空块数、副本间接受率方差、draft/target 前向耗时比；三级指标是分布对账散度（低频）。每个二级指标配一条闸门规则，例如“$\\bar{A}$ 低于盈亏平衡点持续 N 个窗口”“悬空块数单调上升”“副本方差超阈值”，触发时自动执行回滚动作而非仅告警。</p>\n<p>回滚的对象要分层：draft 权重版本回滚（最快，直接恢复接受率）、γ 回滚到更小值（降低候选 KV 峰值与全拒轮代价）、decode 模式回滚到纯 target（保时延不保吞吐）、引擎版本回滚（针对精度对账失败）。伪代码思路：闸门判定为布尔函数，输入是滑动窗口内的指标向量，输出是回滚层级；回滚执行后进入观察期，观察期内指标未恢复则升级到下一层。系统代价：回滚本身有状态迁移成本——draft 权重回滚需要重新加载并清空候选 KV，纯 target 回滚会让在途请求的加速收益归零；因此闸门阈值要留出抖动余量，避免在正常方差内反复触发。具体例子：某次策略更新后 $\\bar{A}$ 连续多个窗口低于盈亏平衡点，闸门先回滚 draft 权重版本，观察期接受率未恢复（说明是策略漂移而非版本问题），升级为 γ 减半并切部分请求到纯 target，rollout 吞吐止跌；随后训练侧用新策略样本重训 draft 并重新上线，接受率回到正常区间。这条链路的工程判断是：接受率是投机 rollout 的“血压”，先看它，再看吞吐。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-47\">四十七 · 失效链与回滚判据：接受率塌陷、KV 碎片与批抖动</h3>\n<p>投机采样在 RL rollout 里的失效往往不是单点故障，而是一条链：策略更新→draft 失配→接受率下降→每步有效 token 数变少→在同样的 SLO 下批被拉长。用公式量化这条链，每轮验证的期望产出为 <span class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}$$</span>，其中 α 是逐位置接受率。当 α 从高位跌到低位时，E 迅速退化到接近 1，此时 <span class=\"formula\">$$\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</span> 的分母仍带着 γ 次 draft 前向的开销，加速比跌破 1，rollout 吞吐反而低于纯目标模型解码。诊断上应把 α 与 γ 一起作为一等指标采集：按请求类型（代码、格式化输出、自由文本 CoT）分桶统计 α，并在同一桶内比较“投机开/关”两条路径的 tokens/s，而不是只看全局均值——全局均值会被高接受率的短样本稀释，掩盖长 CoT 上的负收益。</p>\n<p>第二类失效在显存侧。被拒绝候选的 KV 必须整段丢弃，这要求块表与已接受前缀严格对齐；若 rollout 引擎在拒绝后只回退序列长度而未回收物理块，长 CoT 样本（数千 token）会持续占用无效块，KV 池容量被蚕食，表现为 OOM 或被迫降低并发批。监控应盯“已分配块数 / 有效 token 数”这一比值，它随拒绝率上升而单调恶化；一旦超过阈值即触发块表一致性校验与碎片整理。同时 draft 模型本身常驻一份权重，与目标模型的同步链路多一份模型，显存与同步开销随规模上升，这是投机方案在 NVL72 这类高带宽域内的固定税，不能靠调批大小摊薄。</p>\n<p>第三类是批抖动与尾延迟尖刺。continuous batching 下，一条请求在拒绝处只前进一个 token，其 KV 增量写入远小于接受段，导致同一批内各序列的推进步长不均；调度器若按“每轮固定 γ”分配算力，短推进序列会拖住整批的验证前向，尾延迟出现尖刺。可用一张小表把三类症状与处置对齐：</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>根因</th><th>处置</th></tr></thead><tbody><tr><td>α 分桶后骤降、加速比 &lt;1</td><td>策略漂移，draft 滞后</td><td>回滚到纯目标解码，或按桶关闭投机</td></tr><tr><td>块/有效 token 比上升、OOM</td><td>拒绝段 KV 未回收</td><td>块表校验 + 碎片整理，降并发</td></tr><tr><td>批内步长离散、尾延迟尖刺</td><td>推进不均</td><td>按序列动态调 γ，短推进序列降 γ</td></tr></tbody></table>\n<p>回滚判据要工程化而非凭感觉：以“分桶 α 低于阈值且该桶 tokens/s 低于纯解码基线”作为双条件触发，回滚动作是仅对该请求类型关闭投机、保留 draft 权重但不再参与验证，避免全局切换带来的批重排抖动。γ 也应作为可调旋钮随 α 反馈：α 高时放大 γ 摊薄 draft 开销，α 低时收缩 γ 减少无效验证，这比一刀切关闭更能守住 rollout 样本吞吐的 SLO。</p>\n<h3 id=\"alg-speculative-rollout-draft-sec-48\">四十八 · 同族算法的分界线：改哪一段数据流</h3>\n<p>把投机采样放回同族算法里做选择，第一刀不该切在“谁更快”，而该切在“它改的是rollout数据流的哪一段”。本卷其他条目各自锁定一段：分页KV批量Rollout改的是KV的物理组织与块表；分块预填背驮解码改的是prefill与decode的拼接方式；预填解码分离Rollout改的是两阶段落在不同资源池；KV中心分离式池化改的是KV的归属与跨实例复用；特征级投机采样Rollout改的是候选的构造层（在特征/隐状态上做草稿）；NVFP4量化Rollout稳定化改的是数值精度通路；批不变Rollout采样改的是采样算子对批组成的敏感性；异步Rollout流水线改的是请求在时间轴上的重叠。投机采样（draft-verify）只动decode循环内部：把“逐token串行”换成“γ个候选并行验证”。这条分界线决定了它的收益不来自调度、不来自显存复用、不来自精度压缩，而只来自**每步产出token数的期望值**与**验证前向的摊销比**。</p>\n<p>因此选型时先问一句：当前rollout的瓶颈是否真的落在decode的串行token步上？如果瓶颈是prefill的长提示、是KV池容量不足导致的抢占、是跨实例KV搬运的带宽，那么投机采样即使把decode步数压下去，端到端也拿不到对应的收益——它只压缩了整条时间线里属于decode的那一段。反过来，若profile显示长CoT样本的生成时间占rollout总时长主导，且decode阶段HBM带宽受限而算力闲置，则投机采样正对靶心：它用闲置的算力换掉受限的带宽访问，把每步一次的目标模型前向摊到γ个token上。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>\n<p>这个式子就是选型的分水岭。分子由接受率α与候选长度γ共同决定；分母是每轮的真实代价比——draft自回归γ步的成本与目标模型一次并行验证的成本之比。当α高（代码、格式化输出、结构化JSON），分子接近γ+1量级，分母被draft的小模型成本轻微抬高，净加速成立；当α因策略漂移跌到低位，分子趋近1，分母仍背着γ·c_draft，加速比掉到1以下，rollout吞吐反而下降。这就是为什么“是否选它”不能只看模型大小，必须先估α。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-49\">四十九 · 决策表：五个判据与三种结论</h3>\n<p>把选型做成可执行的判定，需要五个判据：瓶颈位置、接受率稳定性、draft与目标的同步代价、显存余量、以及是否要求输出分布严格无偏。下表给出与相邻算法的对照，结论列只写“选/不选/先修别的”。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>判据</th><th>投机采样（本条目）</th><th>相邻算法</th><th>结论</th></tr>\n</thead>\n<tbody>\n<tr><td>瓶颈在decode串行token步</td><td>直接压缩步数，收益线性于E[tokens/step]</td><td>分页KV/分离式池化改的是容量与搬运，不压步数</td><td>选</td></tr>\n<tr><td>瓶颈在prefill长提示</td><td>几乎无收益，decode占比小</td><td>分块预填背驮解码、预填解码分离把prefill摊薄或隔离</td><td>不选，先修prefill</td></tr>\n<tr><td>接受率α随策略更新剧烈漂移</td><td>加速比可能低于1，负收益</td><td>批不变采样、量化稳定化不依赖α</td><td>不选，或先做draft重训链路</td></tr>\n<tr><td>draft与目标同步链路带宽紧张、显存无余量</td><td>多一份模型权重与同步开销</td><td>KV中心池化把显存花在KV上收益更直接</td><td>先修显存，再评估</td></tr>\n<tr><td>要求输出分布严格无偏</td><td>接受-残差重采样保证无偏</td><td>近似加速（剪枝、早停）有偏</td><td>选，且是唯一无偏选项</td></tr>\n</tbody>\n</table>\n<p>三种结论要落到工程动作上。“选”意味着在decode循环里插入draft-verify，并把γ作为可调参数纳入容量规划；“不选，先修prefill”意味着把预算投到分块预填或分离式部署，投机采样留到prefill不再是主项之后再上；“不选，或先做draft重训链路”意味着先解决同步滞后，否则上线即负收益。注意表中没有“都上”这一行：同族算法并非互斥，但同时上会叠加显存与同步开销，必须按瓶颈排序，一次只动一段数据流，否则无法归因收益。</p>\n<p>具体例子：一个以长CoT数学推理为主的rollout负载，样本数千token，profile显示decode占总时长主导但接受率在训练早期只有低位——此时正确动作不是调大γ，而是先把draft蒸馏链路接上，让draft跟随策略更新；在α稳定之前，γ取小值以压低分母里的γ·c_draft，把负收益风险摁住。反之，代码生成类负载α天然高，可直接取较大γ吃满2–3倍区间。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-50\">五十 · γ与成本的联合选择：不是越大越好</h3>\n<p>γ的选择是同族算法选型里最容易被拍脑袋的一项。由E[tokens/step]的几何级数形式可知，γ增大带来的边际收益随α衰减：α高时每加一个候选位置几乎都能被接受，α低时新增位置大概率在首个拒绝处被截断，白付draft成本。分母的γ·c_draft/c_target是线性增长的，于是存在一个由α与成本比共同决定的最优γ。工程上把它写成扫描：固定目标模型与draft，测若干γ下的实际tokens/step与每步墙钟，取吞吐拐点。伪代码思路是——对每个γ，跑固定长度样本，记录接受前缀长度分布，用实测α代入公式预测，再与实测墙钟比对，偏差大则说明验证前向的并行度没吃满（批太小或候选布局不佳）。</p>\n<p>系统代价在这里体现得最直白：γ增大抬高单轮验证的算力占用与临时激活显存，同时拉长单轮时延的尾部——若SLO卡的是decode时延而非吞吐，大γ会让P99变差，因为一轮验证要等γ个位置全部算完才出结果。批大小与γ是耦合的：continuous batching下每轮对γ个候选并行验证，批越大验证前向越能摊薄固定开销，但KV增量写入的粒度也随γ变化。被拒绝候选的KV必须丢弃且块表保持一致，否则长CoT样本下KV池被无效块占用，容量规划会失准。</p>\n<p>具体例子：同一台机器上，γ从较小值提到较大值时，若实测tokens/step没有按公式预期上升，先查两件事——draft与目标的tokenizer/KV布局是否一致（不一致会引入额外对齐开销），以及批内是否存在大量短样本把验证前向的有效并行度拉低。这两项都属于部署配方层面的错配，不是γ本身的问题。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-51\">五十一 · 与近似加速的取舍：无偏是硬约束</h3>\n<p>同族里还有一类“近似加速”：在线Rollout剪枝砍掉低概率分支、早停截断、以及各种降低候选质量的启发式。它们与投机采样的本质区别不在速度，而在分布。投机采样的接受-残差重采样保证输出分布与目标模型严格一致，逐位置接受概率为</p>\n<div class=\"formula\">$$p_{\\text{accept}}=\\min\\left(1,\\frac{p_{\\text{target}}(x)}{p_{\\text{draft}}(x)}\\right)$$</div>\n<p>拒绝处从残差分布$$\\left(p_{\\text{target}}-p_{\\text{draft}}\\right)^{+}$$重采样一个token。这条性质对RL rollout不是锦上添花而是硬约束：rollout引擎记录每token的logprob供训练侧重要性采样使用，若输出分布被系统性偏移，重要性权重会失配，策略梯度被污染，且这种污染不会在loss曲线上立刻显形。因此当负载对分布保真敏感（on-policy RL、需要精确KL估计的场景），近似加速应让位；投机采样是唯一能在保持无偏的前提下压缩decode步数的选项。</p>\n<p>代价是它把复杂度转移到了draft侧：draft模型需随策略更新频繁重训或蒸馏，rollout与训练的权重同步链路多一份模型，显存与同步开销增加。这与特征级投机采样Rollout形成对照——后者在特征层构造候选，省掉独立draft模型的一部分开销，但对目标模型的内部结构耦合更深，跨模型版本迁移更脆。选型判断是：若团队能维护一条稳定的draft蒸馏流水线且显存有余量，走token级draft-verify；若显存紧张且目标模型结构固定，评估特征级方案；若两者都做不到，退回不做投机，把预算给KV与调度。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-52\">五十二 · 组合顺序与回退条件</h3>\n<p>同族算法可以组合，但顺序有讲究。正确的叠加次序是：先解决容量与搬运（分页KV、KV池化），再解决prefill占比（分块预填、分离式部署），最后在decode循环内插投机采样。理由是可归因性——投机采样的收益依赖α，而α会被批组成、KV布局、量化精度共同影响；若先上投机再改KV组织，接受率的变化无法归因，γ的调参会反复推翻。另一个理由是显存：draft模型要多占一份权重，若KV池已经吃紧，先上投机只会把抢占触发得更频繁，长CoT样本的尾部时延恶化。</p>\n<p>回退条件是选型必须预先写死的。三条硬回退：其一，实测加速比持续低于1（α长期低位），立即摘掉draft-verify，恢复纯目标模型decode，避免负收益拖住整条rollout流水线；其二，权重同步滞后超过一个可接受窗口导致α抖动，先降γ再评估是否暂停投机；其三，KV碎片因拒绝候选的块表不一致而累积，先修块表一致性再谈性能。回退不是失败，而是把投机采样当作可开关的档位——它的收益是条件性的，工程判断的核心是把条件测出来并守住。</p>\n<p>具体到容量规划：把γ、α、draft成本比三个量纳入SLO模型，按最坏α估算所需目标模型副本数，按最好α估算上限，两者之差就是投机采样能兑现的弹性空间。若这个空间不足以覆盖draft带来的显存与同步开销，结论就是不选——不是因为算法不好，而是因为在这套硬件档位与负载配方下，它的条件不成立。</p>\n\n<h3 id=\"alg-speculative-rollout-draft-sec-53\">五十三 · 同族算法怎么选：投机采样的决策边界与失效条件</h3>\n<p>与Rollout前缀KV共享、分块预填搭载解码、分离式预填/解码这些同族手段相比，投机采样不触碰prefill与KV的组织方式，只在decode循环内部用draft-verify并行验证压缩逐token串行开销；而前三者的收益来自跨请求复用或阶段解耦，与本方案正交，可叠加但不可互相替代。选型的第一判据是<strong>接受率α</strong>，而非模型规模或硬件档位：由<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/step}] = \\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha},\\quad \\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens/step}]}{1 + \\gamma\\cdot c_{\\text{draft}}/c_{\\text{target}}}$$</div>可见，当α趋近于1时每轮期望产出接近γ+1个token，加速比由分母中draft前向的相对代价$c_{\\text{draft}}/c_{\\text{target}}$决定；一旦α跌落，分子迅速退化为接近1，而分母仍背着γ次draft前向的开销，加速比跌破1即为负收益。RL早期策略分布漂移大，draft与当前策略不匹配正是α骤降的典型触发条件。</p>\n<p>据此给出决策表，按运行阶段而非算法优劣排序：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选择</th><th>系统代价</th></tr></thead><tbody><tr><td>策略已收敛、输出结构化（代码、格式化）</td><td>投机采样，γ取中等值</td><td>decode吞吐提升2–3倍，显存多一份draft权重</td></tr><tr><td>RL早期、策略漂移剧烈</td><td>关闭或降γ，退回普通decode</td><td>避免负收益；牺牲潜在加速</td></tr><tr><td>长CoT数千token、KV池紧张</td><td>投机采样＋前缀KV共享并用</td><td>被拒候选KV丢弃需块表一致，否则KV碎片累积占用KV池</td></tr><tr><td>draft同步链路带宽不足</td><td>降低重训/蒸馏频率或改用轻量头</td><td>同步滞后拉低α，显存与同步开销随规模上升</td></tr></tbody></table>\n<p>边界条件集中在两处。其一是<strong>同步链路</strong>：draft需随策略更新频繁重训或蒸馏，rollout与训练之间多一份模型权重，显存容量与同步带宽共同构成规模上限——目标模型越大，draft蒸馏成本与权重传输开销越高，γ的可用上限反而被压缩。其二是<strong>KV一致性</strong>：被拒绝候选的KV必须整段丢弃且块表同步回收，长CoT样本下若块表滞后，无效块持续占用KV池，容量压力会先于算力成为瓶颈。工程判断是：把α作为在线监控指标接入rollout调度器，低于阈值即自动降γ或旁路投机路径，用输出分布无偏这一性质保证旁路切换不影响训练侧重要性采样的正确性。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 批量生成调度与前缀共享</td></tr><tr><td>解决什么</td><td>RL rollout的decode阶段是逐token串行，HBM带宽受限而算力闲置，长CoT样本（数千token）的生…</td></tr><tr><td>一句话机制</td><td>用一个小draft模型（或Medusa/EAGLE头）一次猜出γ个候选token，目标模型一次前向并行验证这γ个tok…</td></tr><tr><td>代价与失效</td><td>RL训练早期策略分布漂移大，draft模型与当前策略不匹配导致接受率骤降，加速比可能低于1（负收益）；draft模型需随策略更新频繁重训或…</td></tr><tr><td>后继</td><td>分块预填背驮解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-speculative-rollout-draft · 共 8 个片段</p>\n";break;}}})();
